#!/usr/bin/env python3
# usage: ptyrun.py COLS ROWS cmd args...   -- runs cmd in a pty of given size, dumps raw output to stdout
import os, pty, sys, fcntl, termios, struct, select, signal

cols = int(sys.argv[1]); rows = int(sys.argv[2]); cmd = sys.argv[3:]
pid, fd = pty.fork()
if pid == 0:
    os.execvp(cmd[0], cmd)
else:
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b''
    stdin_data = os.environ.get('PTY_STDIN', '').encode()
    if stdin_data:
        os.write(fd, stdin_data)
    while True:
