{"command":"cd /workspace/src && cat > util.go <<'EOF'
package main

import (
	"bufio"
	"crypto/rand"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"
	"unsafe"
)

// ExitFail prints a red error message to stderr and exits with status 1.
func ExitFail(format string, a ...interface{}) {
	fmt.Fprintf(os.Stderr, "\033[31m"+format+"\033[0m\n", a...)
	os.Exit(1)
}

// ExitFailMsg prints an already formatted message in red and exits.
func ExitFailMsg(msg string) {
	fmt.Fprintf(os.Stderr, "\033[31m%s\033[0m\n", msg)
	os.Exit(1)
}

// ConfirmOrAbort asks the user a yes/no question on stderr.
func ConfirmOrAbort(format string, a ...interface{}) {
	fmt.Fprintf(os.Stderr, format+" [y/n] ", a...)
	reader := bufio.NewReader(os.Stdin)
	input, err := reader.ReadString('\n')
	if err != nil {
		panic(err)
	}
	input = strings.ToLower(strings.TrimSpace(input))
	if input == "y" || input == "yes" {
		return
	}
	ExitFail("Aborted.")
}

// MustGetUUID4String generates a random version 4 UUID.
func MustGetUUID4String() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic(err)
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

// IsValidUUID4String checks for the canonical lower/upper case hex form.
func IsValidUUID4String(s string) bool {
	if len(s) != 36 {
		return false
	}
	for i, c := range s {
		switch i {
		case 8, 13, 18, 23:
			if c != '-' {
				return false
			}
		case 14:
			if c != '4' {
				return false
			}
		case 19:
			if !strings.ContainsRune("89abAB", c) {
				return false
			}
		default:
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return false
			}
		}
	}
	return true
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// MustExpandHome expands a leading ~ to the user's home directory.
func MustExpandHome(path string) string {
	if strings.HasPrefix(path, "~/") || path == "~" {
		home, err := os.UserHomeDir()
		if err != nil {
			ExitFail("Could not determine home directory")
		}
		return filepath.Join(home, path[1:])
	}
	return path
}

func StrSliceContains(haystack []string, needle string) bool {
	for _, s := range haystack {
		if s == needle {
			return true
		}
	}
	return false
}

func IntSliceContains(haystack []int, needle int) bool {
	for _, s := range haystack {
		if s == needle {
			return true
		}
	}
	return false
}

// DeduplicateStrings removes duplicates, preserving first occurrence order.
func DeduplicateStrings(ss []string) []string {
	seen := make(map[string]bool)
	out := make([]string, 0, len(ss))
	for _, s := range ss {
		if !seen[s] {
			seen[s] = true
			out = append(out, s)
		}
	}
	return out
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

// getTermSize returns the width and height of the terminal attached to fd.
func getTermSize(fd uintptr) (int, int, error) {
	ws := &winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if errno != 0 {
		return 0, 0, errno
	}
	return int(ws.Col), int(ws.Row), nil
}

// isTerminal reports whether fd refers to a terminal.
func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

// StdoutIsTTY returns true if stdout is a terminal, or the fake PTY env var is set.
func StdoutIsTTY() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	return isTerminal(os.Stdout.Fd())
}

// RealStdoutIsTTY ignores the fake PTY override.
func RealStdoutIsTTY() bool {
	return isTerminal(os.Stdout.Fd())
}

// MustGetTermSize returns the terminal size, or the fake size when faking.
func MustGetTermSize() (int, int) {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		if !isTerminal(os.Stdout.Fd()) {
			return FakeTermWidth, FakeTermHeight
		}
	}
	w, h, err := getTermSize(os.Stdout.Fd())
	if err != nil {
		return FakeTermWidth, FakeTermHeight
	}
	return w, h
}

// MustRunCmd runs a command with inherited stdio, exiting on failure.
func RunCmdInteractive(name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// MustEditBytes opens the user's editor on a temporary file containing data
// and returns the edited contents. The temporary file is removed on success.
func MustEditBytes(data []byte, tmpPattern string) []byte {
	editor, ok := os.LookupEnv("EDITOR")
	if !ok {
		editor = "vim"
	}

	tmpfile, err := os.CreateTemp("", tmpPattern)
	if err != nil {
		ExitFail("Could not create temporary file to edit")
	}
	name := tmpfile.Name()
	if _, err := tmpfile.Write(data); err != nil {
		ExitFail("Could not write to temporary file to edit")
	}
	tmpfile.Close()

	parts := strings.Fields(editor)
	var cmd *exec.Cmd
	if len(parts) == 0 {
		cmd = exec.Command(editor, name)
	} else {
		cmd = exec.Command(parts[0], append(parts[1:], name)...)
	}
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		ExitFail("Failed to run $EDITOR")
	}

	data, err = os.ReadFile(name)
	if err != nil {
		ExitFail("Could not read back temporary file")
	}
	os.Remove(name)
	return data
}

// MustOpenBrowser launches the system URL handler without waiting for it.
func MustOpenBrowser(url string) {
	cmd := exec.Command("xdg-open", url)
	if err := cmd.Start(); err != nil {
		ExitFail("Failed to open browser")
	}
}
EOF
echo ok"}

