{"command":"cd /workspace/src && cat > query.go <<'EOF'
package main

import (
	"strconv"
	"strings"
	"time"
)

// Query represents the parsed command line: command, IDs, filters and text.
// Field order and names are significant for gob compatibility of the stored
// context (state.bin).
type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

func isCmd(s string) bool {
	return StrSliceContains(AllCmds, s)
}

func isPriority(s string) bool {
	return StrSliceContains(AllPriorities, s)
}

// ParseQuery parses command line arguments into a Query.
func ParseQuery(args ...string) Query {
	var q Query
	var words []string
	var noteWords []string
	idsExhausted := false
	noteMode := false

	for _, item := range args {
		if noteMode {
			noteWords = append(noteWords, item)
			continue
		}

		if item == NoteModeKeyword {
			noteMode = true
			continue
		}

		if item == IgnoreContextKeyword {
			q.IgnoreContext = true
			idsExhausted = true
			continue
		}

		if q.Cmd == "" && isCmd(item) {
			q.Cmd = item
			continue
		}

		if !idsExhausted {
			if id, err := strconv.Atoi(item); err == nil {
				q.IDs = append(q.IDs, id)
				continue
			}
		}
		idsExhausted = true

		lcItem := strings.ToLower(item)

		switch {
		case strings.HasPrefix(lcItem, "project:"):
			if q.Project == "" {
				q.Project = lcItem[len("project:"):]
			} else {
				words = append(words, item)
			}
		case strings.HasPrefix(lcItem, "-project:"):
			q.AntiProjects = append(q.AntiProjects, lcItem[len("-project:"):])
		case len(item) > 1 && item[0] == '+':
			q.Tags = append(q.Tags, lcItem[1:])
		case len(item) > 1 && item[0] == '-':
			q.AntiTags = append(q.AntiTags, lcItem[1:])
		case isPriority(item):
			if q.Priority == "" {
				q.Priority = item
			} else {
				words = append(words, item)
			}
		case strings.HasPrefix(lcItem, "due:"):
			if !q.Due.IsZero() {
				ExitFail("Query should only have one due date")
			}
			due, err := ParseDueDate(lcItem[len("due:"):])
			if err != nil {
