	"thursday":  time.Thursday,
	"thurs":     time.Thursday,
	"thur":      time.Thursday,
	"thu":       time.Thursday,
	"friday":    time.Friday,
	"fri":       time.Friday,
	"saturday":  time.Saturday,
	"sat":       time.Saturday,
}

var errInvalidDate = errors.New("invalid date")

// startOfDay returns midnight (local) for the given time.
func startOfDay(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
}

// ParseDueDate parses the value of a due: operator. The input is expected
// to be lower case already.
func ParseDueDate(s string) (time.Time, error) {
	now := time.Now()
	today := startOfDay(now)

	if t, err := time.ParseInLocation("2006-01-02", s, time.Local); err == nil {
		return t, nil
	}
	if t, err := time.Parse("01-02", s); err == nil {
		return time.Date(now.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.Local), nil
	}
	if t, err := time.Parse("2", s); err == nil {
		return time.Date(now.Year(), now.Month(), t.Day(), 0, 0, 0, 0, time.Local), nil
	}

	switch s {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	case "yesterday":
		return today.AddDate(0, 0, -1), nil
	}

	// start of the current week (sunday)
	thisSunday := today.AddDate(0, 0, -int(today.Weekday()))

	if wd, ok := weekdayNames[s]; ok {
		return today.AddDate(0, 0, (int(wd)-int(today.Weekday())+7)%7), nil
	}
	if strings.HasPrefix(s, "this-") {
		if wd, ok := weekdayNames[s[len("this-"):]]; ok {
			return today.AddDate(0, 0, (int(wd)-int(today.Weekday())+7)%7), nil
		}
	}
	if strings.HasPrefix(s, "next-") {
		if wd, ok := weekdayNames[s[len("next-"):]]; ok {
			return thisSunday.AddDate(0, 0, 7+int(wd)), nil
		}
	}
	if strings.HasPrefix(s, "last-") {
		if wd, ok := weekdayNames[s[len("last-"):]]; ok {
			return thisSunday.AddDate(0, 0, int(wd)), nil
		}
	}

	return time.Time{}, errInvalidDate
}

func sameDate(a, b time.Time) bool {
	return a.Year() == b.Year() && a.YearDay() == b.YearDay()
}

// FormatDue renders a due date relative to now for the task tables.
func FormatDue(due time.Time) string {
	if due.IsZero() {
		return ""
	}
	now := time.Now()
	today := startOfDay(now)

	switch {
	case sameDate(due, now):
		return "today"
	case sameDate(due, now.AddDate(0, 0, 1)):
		return "tomorrow"
	case sameDate(due, now.AddDate(0, 0, -1)):
		return "yesterday"
	}

	if due.After(now) && due.Before(today.AddDate(0, 0, 7)) {
		return due.Format("Mon 2")
	}
	if due.Year() == now.Year() {
		return due.Format("_2 Jan")
	}
	return due.Format("_2 Jan 2006")
}

// FormatResolved renders the resolved column for the weekly report.
func FormatResolved(t time.Time) string {
	return t.Format("Mon 2")
}
EOF
echo ok"}

