type SubTask struct {
	Summary  string
	Resolved bool
}

// Task is the main data structure. Fields serialised to YAML are the ones
// after ID (summary onwards); UUID/status/ID are derived from the file
// location.
type Task struct {
	UUID   string `json:"uuid"`
	Status string `json:"status"`
	ID     int    `json:"id"`

	Summary      string    `json:"summary"`
	Notes        string    `json:"notes"`
	Tags         []string  `json:"tags"`
	Project      string    `json:"project"`
	Priority     string    `json:"priority"`
	DelegatedTo  string    `json:"-"`
	Subtasks     []SubTask `json:"-"`
	Dependencies []string  `json:"-"`
	Created      time.Time `json:"created"`
	Resolved     time.Time `json:"resolved"`
	Due          time.Time `json:"due"`

	// internal bookkeeping
	writePending bool
	deleted      bool
	filtered     bool
}

// Normalise cleans up tags etc. prior to saving.
func (t *Task) Normalise() {
	if t.Tags == nil {
		t.Tags = []string{}
	}
	t.Tags = DeduplicateStrings(t.Tags)
	sort.Strings(t.Tags)

	if t.Status == StatusResolved && t.Resolved.IsZero() {
		t.Resolved = time.Now()
	}
}

// Validate checks the task is sane, returning an error message or "".
func (t *Task) Validate() error {
	if !IsValidUUID4String(t.UUID) {
		return fmt.Errorf("invalid task UUID4")
	}
	if !StrSliceContains(AllStatuses, t.Status) {
		return fmt.Errorf("invalid status specified on task")
	}
	if !isPriority(t.Priority) {
		return fmt.Errorf("invalid priority specified")
	}
	for _, uuid := range t.Dependencies {
		if !IsValidUUID4String(uuid) {
			return fmt.Errorf("invalid dependency UUID4")
		}
	}
	return nil
}

// SetStatus changes the status, enforcing valid transitions.
func (t *Task) SetStatus(status string) error {
	valid := false
	switch status {
	case StatusActive:
		valid = t.Status == StatusPending || t.Status == StatusPaused || t.Status == StatusActive
	case StatusPaused:
		valid = t.Status == StatusActive || t.Status == StatusPaused
	case StatusResolved:
		valid = t.Status == StatusPending || t.Status == StatusActive || t.Status == StatusPaused
	case StatusPending:
		valid = t.Status == StatusPending
	default:
		valid = false
	}
	if !valid {
		return fmt.Errorf("invalid state transition: %s -> %s", t.Status, status)
	}
	if status == StatusResolved {
		t.Resolved = time.Now()
	}
	t.Status = status
	t.writePending = true
	return nil
}

// Modify applies the attributes of a query to the task.
func (t *Task) Modify(query Query) {
	for _, tag := range query.Tags {
		if !StrSliceContains(t.Tags, tag) {
			t.Tags = append(t.Tags, tag)
		}
	}
	var tags []string
	for _, tag := range t.Tags {
		if !StrSliceContains(query.AntiTags, tag) {
			tags = append(tags, tag)
		}
	}
	t.Tags = tags
	if t.Tags == nil {
		t.Tags = []string{}
	}

	if query.Project != "" {
		t.Project = query.Project
	}
	if StrSliceContains(query.AntiProjects, t.Project) {
		t.Project = ""
	}
	if query.Priority != "" {
		t.Priority = query.Priority
	}
	if !query.Due.IsZero() {
		t.Due = query.Due
	}
	if t.Notes == "" {
		t.Notes = query.Note
	} else {
		t.Notes = t.Notes + "\n" + query.Note
	}
	t.writePending = true
}

// MatchesFilter reports whether the task matches the filter query.
func (t *Task) MatchesFilter(query Query) bool {
	if len(query.IDs) > 0 && !IntSliceContains(query.IDs, t.ID) {
		return false
	}
	for _, tag := range query.Tags {
		if !StrSliceContains(t.Tags, tag) {
			return false
		}
	}
	for _, tag := range query.AntiTags {
		if StrSliceContains(t.Tags, tag) {
			return false
		}
	}
	if query.Project != "" && t.Project != query.Project {
		return false
	}
	if StrSliceContains(query.AntiProjects, t.Project) {
		return false
	}
	if query.Priority != "" && t.Priority != query.Priority {
		return false
	}
	if !query.Due.IsZero() && !t.Due.Equal(query.Due) {
		return false
	}
	if query.Text != "" {
		lcText := strings.ToLower(query.Text)
		if !strings.Contains(strings.ToLower(t.Summary), lcText) &&
			!strings.Contains(strings.ToLower(t.Notes), lcText) {
			return false
		}
	}
	return true
}

// LongSummary returns the summary with the last line of the notes appended
// (used by the task table). The second return value indicates where the
// note portion starts (rune offset), or -1 if there is none.
func (t *Task) NoteTail() string {
	notes := strings.TrimSpace(t.Notes)
	if notes == "" {
		return ""
	}
	lines := strings.Split(notes, "\n")
	return lines[len(lines)-1]
}

// IsOverdue is true when the due date has passed.
func (t *Task) IsOverdue() bool {
	return !t.Due.IsZero() && t.Due.Before(time.Now())
}

// TaskFromQuery creates a new task from the attributes of a query.
func TaskFromQuery(query Query) Task {
	task := Task{
		UUID:     MustGetUUID4String(),
		Status:   StatusPending,
		Summary:  query.Text,
		Tags:     []string{},
		Project:  query.Project,
		Priority: query.Priority,
		Notes:    query.Note,
		Due:      query.Due,
	}
	for _, tag := range query.Tags {
		if !StrSliceContains(task.Tags, tag) {
			task.Tags = append(task.Tags, tag)
		}
	}
	if task.Priority == "" {
		task.Priority = PriorityNormal
	}
	return task
}

// Tasks is a sortable slice of task pointers.
type Tasks []*Task

func (ts Tasks) Len() int      { return len(ts) }
func (ts Tasks) Swap(i, j int) { ts[i], ts[j] = ts[j], ts[i] }
func (ts Tasks) Less(i, j int) bool {
	if ts[i].Priority != ts[j].Priority {
		return ts[i].Priority < ts[j].Priority
	}
	return ts[i].Created.Before(ts[j].Created)
}

// ByResolved sorts by resolved time ascending.
type ByResolved Tasks

func (ts ByResolved) Len() int           { return len(ts) }
func (ts ByResolved) Swap(i, j int)      { ts[i], ts[j] = ts[j], ts[i] }
func (ts ByResolved) Less(i, j int) bool { return ts[i].Resolved.Before(ts[j].Resolved) }
