// This file implements a small YAML emitter which reproduces the output of
// the libyaml-derived emitter for the subset of YAML used by task files:
// a top level block mapping of scalars, sequences of scalars and sequences
// of small mappings.

const yamlBestWidth = 80
const yamlBestIndent = 2

type yamlEmitter struct {
	buf        bytes.Buffer
	column     int
	whitespace bool
	indention  bool
	indent     int
}

func newYamlEmitter() *yamlEmitter {
	return &yamlEmitter{whitespace: true, indention: true, indent: -1}
}

func (e *yamlEmitter) put(c byte) {
	e.buf.WriteByte(c)
	e.column++
}

func (e *yamlEmitter) putBreak() {
	e.buf.WriteByte('\n')
	e.column = 0
}

// writeRune writes one UTF-8 character starting at value[i], returning the
// new index.
func (e *yamlEmitter) writeChar(value string, i int) int {
	_, w := utf8.DecodeRuneInString(value[i:])
	e.buf.WriteString(value[i : i+w])
	e.column++
	return i + w
}

func (e *yamlEmitter) writeBreak(value string, i int) int {
	if value[i] == '\n' {
		e.putBreak()
		return i + 1
	}
	_, w := utf8.DecodeRuneInString(value[i:])
	e.buf.WriteString(value[i : i+w])
	e.column = 0
	return i + w
}

func (e *yamlEmitter) writeIndent() {
	indent := e.indent
	if indent < 0 {
		indent = 0
	}
	if !e.indention || e.column > indent || (e.column == indent && !e.whitespace) {
		e.putBreak()
	}
	for e.column < indent {
		e.put(' ')
	}
	e.whitespace = true
	e.indention = true
}

func (e *yamlEmitter) writeIndicator(indicator string, needWhitespace, isWhitespace, isIndention bool) {
	if needWhitespace && !e.whitespace {
		e.put(' ')
	}
	for i := 0; i < len(indicator); i++ {
		e.put(indicator[i])
	}
	e.whitespace = isWhitespace
	e.indention = e.indention && isIndention
}

func (e *yamlEmitter) increaseIndent(flow, indentless bool) int {
	old := e.indent
	if e.indent < 0 {
		if flow {
			e.indent = yamlBestIndent
		} else {
			e.indent = 0
		}
	} else if !indentless {
		e.indent += yamlBestIndent
	}
	return old
}

// character classification helpers (operate on bytes of UTF-8 strings)

func yIsSpace(s string, i int) bool { return i < len(s) && s[i] == ' ' }
func yIsBlank(s string, i int) bool { return i < len(s) && (s[i] == ' ' || s[i] == '\t') }
func yIsBreak(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	c := s[i]
	if c == '\r' || c == '\n' {
		return true
	}
	if c == 0xC2 && i+1 < len(s) && s[i+1] == 0x85 {
		return true
	}
	if c == 0xE2 && i+2 < len(s) && s[i+1] == 0x80 && (s[i+2] == 0xA8 || s[i+2] == 0xA9) {
		return true
	}
	return false
}
func yIsBlankz(s string, i int) bool {
	return yIsBlank(s, i) || yIsBreak(s, i) || i >= len(s) || s[i] == 0
}
func yIsBOM(s string, i int) bool {
	return i+2 < len(s) && s[i] == 0xEF && s[i+1] == 0xBB && s[i+2] == 0xBF
}
func yIsPrintable(s string, i int) bool {
	c := s[i]
	switch {
	case c == 0x0A:
		return true
	case c >= 0x20 && c <= 0x7E:
		return true
	case c == 0xC2 && i+1 < len(s) && s[i+1] >= 0xA0:
		return true
	case c > 0xC2 && c < 0xED:
		return true
	case c == 0xED && i+1 < len(s) && s[i+1] < 0xA0:
		return true
	case c == 0xEE:
		return true
	case c == 0xEF && i+2 < len(s) && !(s[i+1] == 0xBB && s[i+2] == 0xBF) && !(s[i+1] == 0xBF && (s[i+2] == 0xBE || s[i+2] == 0xBF)):
		return true
	}
	return false
}

type yamlScalarAnalysis struct {
	multiline          bool
	flowPlainAllowed   bool
	blockPlainAllowed  bool
	singleQuotedAllowed bool
	blockAllowed       bool
