package main

import (
	"bytes"
	"math"
	"regexp"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// This file implements a small YAML emitter which reproduces the output of
// the libyaml-derived emitter for the subset of YAML used by task files:
// a top level block mapping of scalars, sequences of scalars and sequences
// of small mappings.

const yamlBestWidth = 80
const yamlBestIndent = 2

type yamlEmitter struct {
	buf        bytes.Buffer
	column     int
	whitespace bool
	indention  bool
	indent     int
}

func newYamlEmitter() *yamlEmitter {
	return &yamlEmitter{whitespace: true, indention: true, indent: -1}
}

func (e *yamlEmitter) put(c byte) {
	e.buf.WriteByte(c)
	e.column++
}

func (e *yamlEmitter) putBreak() {
	e.buf.WriteByte('\n')
	e.column = 0
}

// writeRune writes one UTF-8 character starting at value[i], returning the
// new index.
func (e *yamlEmitter) writeChar(value string, i int) int {
	_, w := utf8.DecodeRuneInString(value[i:])
	e.buf.WriteString(value[i : i+w])
	e.column++
	return i + w
}

func (e *yamlEmitter) writeBreak(value string, i int) int {
	if value[i] == '\n' {
		e.putBreak()
		return i + 1
	}
	_, w := utf8.DecodeRuneInString(value[i:])
	e.buf.WriteString(value[i : i+w])
	e.column = 0
	return i + w
}

func (e *yamlEmitter) writeIndent() {
	indent := e.indent
	if indent < 0 {
		indent = 0
	}
	if !e.indention || e.column > indent || (e.column == indent && !e.whitespace) {
		e.putBreak()
	}
	for e.column < indent {
		e.put(' ')
	}
	e.whitespace = true
	e.indention = true
}

func (e *yamlEmitter) writeIndicator(indicator string, needWhitespace, isWhitespace, isIndention bool) {
	if needWhitespace && !e.whitespace {
		e.put(' ')
	}
	for i := 0; i < len(indicator); i++ {
		e.put(indicator[i])
	}
	e.whitespace = isWhitespace
	e.indention = e.indention && isIndention
}

func (e *yamlEmitter) increaseIndent(flow, indentless bool) int {
	old := e.indent
	if e.indent < 0 {
		if flow {
			e.indent = yamlBestIndent
		} else {
			e.indent = 0
		}
	} else if !indentless {
		e.indent += yamlBestIndent
	}
	return old
}

// character classification helpers (operate on bytes of UTF-8 strings)

func yIsSpace(s string, i int) bool { return i < len(s) && s[i] == ' ' }
func yIsBlank(s string, i int) bool { return i < len(s) && (s[i] == ' ' || s[i] == '\t') }
func yIsBreak(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	c := s[i]
	if c == '\r' || c == '\n' {
		return true
	}
	if c == 0xC2 && i+1 < len(s) && s[i+1] == 0x85 {
		return true
	}
	if c == 0xE2 && i+2 < len(s) && s[i+1] == 0x80 && (s[i+2] == 0xA8 || s[i+2] == 0xA9) {
		return true
	}
	return false
}
func yIsBlankz(s string, i int) bool {
	return yIsBlank(s, i) || yIsBreak(s, i) || i >= len(s) || s[i] == 0
}
func yIsBOM(s string, i int) bool {
	return i+2 < len(s) && s[i] == 0xEF && s[i+1] == 0xBB && s[i+2] == 0xBF
}
func yIsPrintable(s string, i int) bool {
	c := s[i]
	switch {
	case c == 0x0A:
		return true
	case c >= 0x20 && c <= 0x7E:
		return true
	case c == 0xC2 && i+1 < len(s) && s[i+1] >= 0xA0:
		return true
	case c > 0xC2 && c < 0xED:
		return true
	case c == 0xED && i+1 < len(s) && s[i+1] < 0xA0:
		return true
	case c == 0xEE:
		return true
	case c == 0xEF && i+2 < len(s) && !(s[i+1] == 0xBB && s[i+2] == 0xBF) && !(s[i+1] == 0xBF && (s[i+2] == 0xBE || s[i+2] == 0xBF)):
		return true
	}
	return false
}

type yamlScalarAnalysis struct {
	multiline          bool
	flowPlainAllowed   bool
	blockPlainAllowed  bool
	singleQuotedAllowed bool
	blockAllowed       bool
}

func yamlAnalyzeScalar(value string) yamlScalarAnalysis {
	var a yamlScalarAnalysis
	if len(value) == 0 {
		a.multiline = false
		a.flowPlainAllowed = false
		a.blockPlainAllowed = true
		a.singleQuotedAllowed = true
		a.blockAllowed = false
		return a
	}

	blockIndicators := false
	flowIndicators := false
	lineBreaks := false
	specialCharacters := false

	leadingSpace := false
	leadingBreak := false
	trailingSpace := false
	trailingBreak := false
	breakSpace := false
	spaceBreak := false

	precededByWhitespace := true
	followedByWhitespace := false
	previousSpace := false
	previousBreak := false

	if len(value) >= 3 && ((value[0] == '-' && value[1] == '-' && value[2] == '-') || (value[0] == '.' && value[1] == '.' && value[2] == '.')) {
		blockIndicators = true
		flowIndicators = true
	}

	for i, w := 0, 0; i < len(value); i += w {
		_, w = utf8.DecodeRuneInString(value[i:])
		followedByWhitespace = i+w >= len(value) || yIsBlank(value, i+w)

		if i == 0 {
			switch value[i] {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				flowIndicators = true
				blockIndicators = true
			case '?', ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '-':
				if followedByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		} else {
			switch value[i] {
			case ',', '?', '[', ']', '{', '}':
				flowIndicators = true
			case ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '#':
				if precededByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		}

		if !yIsPrintable(value, i) {
			specialCharacters = true
		}
		if yIsSpace(value, i) {
			if i == 0 {
				leadingSpace = true
			}
			if i+w == len(value) {
				trailingSpace = true
			}
			if previousBreak {
				breakSpace = true
			}
			previousSpace = true
			previousBreak = false
		} else if yIsBreak(value, i) {
			lineBreaks = true
			if i == 0 {
				leadingBreak = true
			}
			if i+w == len(value) {
				trailingBreak = true
			}
			if previousSpace {
				spaceBreak = true
			}
			previousSpace = false
			previousBreak = true
		} else {
			previousSpace = false
			previousBreak = false
		}

		precededByWhitespace = yIsBlankz(value, i)
	}

	a.multiline = lineBreaks
	a.flowPlainAllowed = true
	a.blockPlainAllowed = true
	a.singleQuotedAllowed = true
	a.blockAllowed = true

	if leadingSpace || leadingBreak || trailingSpace || trailingBreak {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
	}
	if trailingSpace {
		a.blockAllowed = false
	}
	if breakSpace {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
		a.singleQuotedAllowed = false
	}
	if spaceBreak || specialCharacters {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
		a.singleQuotedAllowed = false
		a.blockAllowed = false
	}
	if lineBreaks {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
	}
	if flowIndicators {
		a.flowPlainAllowed = false
	}
	if blockIndicators {
		a.blockPlainAllowed = false
	}
	return a
}

type yamlStyle int

const (
	yamlPlain yamlStyle = iota
	yamlSingleQuoted
	yamlDoubleQuoted
	yamlLiteral
)

// yaml resolution (what an unquoted string would be interpreted as)

var yamlResolveMap = map[string]bool{}

func init() {
	for _, s := range []string{
		"y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON",
		"n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF",
		"", "~", "null", "Null", "NULL",
		".nan", ".NaN", ".NAN", ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF",
		"<<",
	} {
		yamlResolveMap[s] = true
	}
}

var yamlStyleFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)
var yamlBase60Float = regexp.MustCompile(`^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+(?:\.[0-9_]*)?$`)

var yamlTimestampFormats = []string{
	"2006-1-2T15:4:5.999999999Z07:00",
	"2006-1-2t15:4:5.999999999Z07:00",
	"2006-1-2 15:4:5.999999999",
	"2006-1-2",
}

func yamlParseTimestamp(s string) (time.Time, bool) {
	i := 0
	for ; i < len(s); i++ {
		if c := s[i]; c < '0' || c > '9' {
			break
		}
	}
	if i != 4 || i == len(s) || s[i] != '-' {
		return time.Time{}, false
	}
	for _, format := range yamlTimestampFormats {
		if t, err := time.Parse(format, s); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

// yamlResolvesToString reports whether the plain scalar would be read back
// as a string (rather than bool/null/number/timestamp).
func yamlResolvesToString(in string) bool {
	if in == "" {
		return false
	}
	var hint byte
	c := in[0]
	switch {
	case c == '+' || c == '-':
		hint = 'S'
	case c >= '0' && c <= '9':
		hint = 'D'
	case strings.IndexByte("yYnNtTfFoO~", c) >= 0:
		hint = 'M'
	case c == '.':
		hint = '.'
	}
	if hint == 0 {
		return true
	}
	if yamlResolveMap[in] {
		return false
	}
	switch hint {
	case 'M':
		return true
	case '.':
		if _, err := strconv.ParseFloat(in, 64); err == nil {
			return false
		}
		return true
	case 'D', 'S':
		if _, ok := yamlParseTimestamp(in); ok {
			return false
		}
		plain := strings.Replace(in, "_", "", -1)
		if _, err := strconv.ParseInt(plain, 0, 64); err == nil {
			return false
		}
		if _, err := strconv.ParseUint(plain, 0, 64); err == nil {
			return false
		}
		if yamlStyleFloat.MatchString(plain) {
			if _, err := strconv.ParseFloat(plain, 64); err == nil {
				return false
			}
		}
		if strings.HasPrefix(plain, "0b") {
			if _, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
				return false
			}
			if _, err := strconv.ParseUint(plain[2:], 2, 64); err == nil {
				return false
			}
		} else if strings.HasPrefix(plain, "-0b") {
			if _, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
				return false
			}
		}
	}
	return true
}

// yamlResolvePlain returns the Go value a plain scalar resolves to; ok is
// false if it is a plain string.
func yamlResolvePlain(in string) (interface{}, string) {
	if in == "" {
		return nil, "!!null"
	}
	var hint byte
	c := in[0]
	switch {
	case c == '+' || c == '-':
		hint = 'S'
	case c >= '0' && c <= '9':
		hint = 'D'
	case strings.IndexByte("yYnNtTfFoO~", c) >= 0:
		hint = 'M'
	case c == '.':
		hint = '.'
	}
	if hint == 0 {
		return in, "!!str"
	}
	if yamlResolveMap[in] {
		switch in {
		case "y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON":
			return true, "!!bool"
		case "n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF":
			return false, "!!bool"
		case "", "~", "null", "Null", "NULL":
			return nil, "!!null"
		case ".nan", ".NaN", ".NAN":
			return math.NaN(), "!!float"
		case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
			return math.Inf(1), "!!float"
		case "-.inf", "-.Inf", "-.INF":
			return math.Inf(-1), "!!float"
		case "<<":
			return in, "!!merge"
		}
	}
	switch hint {
	case 'M':
		return in, "!!str"
	case '.':
		if f, err := strconv.ParseFloat(in, 64); err == nil {
			return f, "!!float"
		}
	case 'D', 'S':
		if t, ok := yamlParseTimestamp(in); ok {
			return t, "!!timestamp"
		}
		plain := strings.Replace(in, "_", "", -1)
		if v, err := strconv.ParseInt(plain, 0, 64); err == nil {
			return v, "!!int"
		}
		if v, err := strconv.ParseUint(plain, 0, 64); err == nil {
			return v, "!!int"
		}
		if yamlStyleFloat.MatchString(plain) {
			if f, err := strconv.ParseFloat(plain, 64); err == nil {
				return f, "!!float"
			}
		}
		if strings.HasPrefix(plain, "0b") {
			if v, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
				return v, "!!int"
			}
			if v, err := strconv.ParseUint(plain[2:], 2, 64); err == nil {
				return v, "!!int"
			}
		} else if strings.HasPrefix(plain, "-0b") {
			if v, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
				return v, "!!int"
			}
		}
	}
	return in, "!!str"
}

// selectStyle chooses the scalar style for a string value the way the
// yaml.v2 encoder + emitter does for a block mapping value / sequence item.
func yamlSelectStringStyle(value string, a yamlScalarAnalysis, simpleKey bool) yamlStyle {
	canUsePlain := yamlResolvesToString(value) && !yamlBase60Float.MatchString(value)
	var style yamlStyle
	switch {
	case strings.Contains(value, "\n"):
		style = yamlLiteral
	case canUsePlain:
		style = yamlPlain
	default:
		style = yamlDoubleQuoted
	}

	if simpleKey && a.multiline {
		style = yamlDoubleQuoted
	}
	if style == yamlPlain {
		if !a.blockPlainAllowed {
			style = yamlSingleQuoted
		}
		if len(value) == 0 && simpleKey {
			style = yamlSingleQuoted
		}
	}
	if style == yamlSingleQuoted {
		if !a.singleQuotedAllowed {
			style = yamlDoubleQuoted
		}
	}
	if style == yamlLiteral {
		if !a.blockAllowed || simpleKey {
			style = yamlDoubleQuoted
		}
	}
	return style
}

func (e *yamlEmitter) writePlainScalar(value string, allowBreaks bool) {
	if !e.whitespace {
		e.put(' ')
	}
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if yIsSpace(value, i) {
			if allowBreaks && !spaces && e.column > yamlBestWidth && !yIsSpace(value, i+1) {
				e.writeIndent()
				i++
			} else {
				i = e.writeChar(value, i)
			}
			spaces = true
		} else if yIsBreak(value, i) {
			if !breaks && value[i] == '\n' {
				e.putBreak()
			}
			i = e.writeBreak(value, i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			i = e.writeChar(value, i)
			e.indention = false
			spaces = false
			breaks = false
		}
	}
	e.whitespace = false
	e.indention = false
}

func (e *yamlEmitter) writeSingleQuotedScalar(value string, allowBreaks bool) {
	e.writeIndicator("'", true, false, false)
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if yIsSpace(value, i) {
			if allowBreaks && !spaces && e.column > yamlBestWidth && i > 0 && i < len(value)-1 && !yIsSpace(value, i+1) {
				e.writeIndent()
				i++
			} else {
				i = e.writeChar(value, i)
			}
			spaces = true
		} else if yIsBreak(value, i) {
			if !breaks && value[i] == '\n' {
				e.putBreak()
			}
			i = e.writeBreak(value, i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			if value[i] == '\'' {
				e.put('\'')
			}
			i = e.writeChar(value, i)
			e.indention = false
			spaces = false
			breaks = false
		}
	}
	e.writeIndicator("'", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *yamlEmitter) writeDoubleQuotedScalar(value string, allowBreaks bool) {
	spaces := false
	e.writeIndicator("\"", true, false, false)
	for i := 0; i < len(value); {
		if !yIsPrintable(value, i) || yIsBOM(value, i) || yIsBreak(value, i) || value[i] == '"' || value[i] == '\\' {
			r, w := utf8.DecodeRuneInString(value[i:])
			if r == utf8.RuneError && w == 1 {
				r = rune(value[i])
			}
			i += w
			e.put('\\')
			switch r {
			case 0x00:
				e.put('0')
			case 0x07:
				e.put('a')
			case 0x08:
				e.put('b')
			case 0x09:
				e.put('t')
			case 0x0A:
				e.put('n')
			case 0x0b:
				e.put('v')
			case 0x0c:
				e.put('f')
			case 0x0d:
				e.put('r')
			case 0x1b:
				e.put('e')
			case 0x22:
				e.put('"')
			case 0x5c:
				e.put('\\')
			case 0x85:
				e.put('N')
			case 0xA0:
				e.put('_')
			case 0x2028:
				e.put('L')
			case 0x2029:
				e.put('P')
			default:
				var digits int
				if r <= 0xFF {
					e.put('x')
					digits = 2
				} else if r <= 0xFFFF {
					e.put('u')
					digits = 4
				} else {
					e.put('U')
					digits = 8
				}
				for k := (digits - 1) * 4; k >= 0; k -= 4 {
					digit := byte((r >> uint(k)) & 0x0F)
					if digit < 10 {
						e.put(digit + '0')
					} else {
						e.put(digit + 'A' - 10)
					}
				}
			}
			spaces = false
		} else if yIsSpace(value, i) {
			if allowBreaks && !spaces && e.column > yamlBestWidth && i > 0 && i < len(value)-1 {
				e.writeIndent()
				if yIsSpace(value, i+1) {
					e.put('\\')
				}
				i++
			} else {
				i = e.writeChar(value, i)
			}
			spaces = true
		} else {
			i = e.writeChar(value, i)
			spaces = false
		}
	}
	e.writeIndicator("\"", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *yamlEmitter) writeBlockScalarHints(value string) {
	if yIsSpace(value, 0) || yIsBreak(value, 0) {
		e.writeIndicator(strconv.Itoa(yamlBestIndent), false, false, false)
	}
	chomp := ""
	if len(value) == 0 {
		chomp = "-"
	} else {
		// last character
		p := len(value) - 1
		for p > 0 && (value[p]&0xC0) == 0x80 {
			p--
		}
		if !yIsBreak(value, p) {
			chomp = "-"
		} else if p == 0 {
			chomp = "+"
		} else {
			q := p - 1
			for q > 0 && (value[q]&0xC0) == 0x80 {
				q--
			}
			if yIsBreak(value, q) {
				chomp = "+"
			}
		}
	}
	if chomp != "" {
		e.writeIndicator(chomp, false, false, false)
	}
}

func (e *yamlEmitter) writeLiteralScalar(value string) {
	breaks := true
	e.writeIndicator("|", true, false, false)
	e.writeBlockScalarHints(value)
	e.putBreak()
	e.indention = true
	e.whitespace = true
	for i := 0; i < len(value); {
		if yIsBreak(value, i) {
			i = e.writeBreak(value, i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			i = e.writeChar(value, i)
			e.indention = false
			breaks = false
		}
	}
}

// emitStringScalar emits a string value node (not a key).
func (e *yamlEmitter) emitStringScalar(value string) {
	a := yamlAnalyzeScalar(value)
	style := yamlSelectStringStyle(value, a, false)
	e.increaseIndent(true, false)
	old := e.indent
	switch style {
	case yamlPlain:
		e.writePlainScalar(value, true)
	case yamlSingleQuoted:
		e.writeSingleQuotedScalar(value, true)
	case yamlDoubleQuoted:
		e.writeDoubleQuotedScalar(value, true)
	case yamlLiteral:
		e.writeLiteralScalar(value)
	}
	_ = old
	e.indent -= yamlBestIndent
}

// emitRawPlain emits a value that is always written plain (timestamps,
// booleans).
func (e *yamlEmitter) emitRawPlain(value string) {
	e.increaseIndent(true, false)
	e.writePlainScalar(value, true)
	e.indent -= yamlBestIndent
}

// emitKey writes a simple mapping key followed by ':'.
func (e *yamlEmitter) emitKey(key string) {
	e.writeIndent()
	a := yamlAnalyzeScalar(key)
	style := yamlSelectStringStyle(key, a, true)
	e.increaseIndent(true, false)
	switch style {
	case yamlPlain:
		e.writePlainScalar(key, false)
	case yamlSingleQuoted:
		e.writeSingleQuotedScalar(key, false)
	default:
		e.writeDoubleQuotedScalar(key, false)
	}
	e.indent -= yamlBestIndent
	e.writeIndicator(":", false, false, false)
}

// yamlMapping is an ordered list of key/value pairs for emission.
type yamlKV struct {
	key   string
	value interface{} // string, yamlRaw, []string, []yamlMapping
}

type yamlRaw string

type yamlMapping []yamlKV

func (e *yamlEmitter) emitMapping(m yamlMapping) {
	e.increaseIndent(false, false)
	savedIndent := e.indent
	for _, kv := range m {
		e.indent = savedIndent
		e.emitKey(kv.key)
		e.emitValue(kv.value)
	}
	e.indent = savedIndent - yamlBestIndent
	if savedIndent == 0 {
		e.indent = -1
	}
}

func (e *yamlEmitter) emitValue(v interface{}) {
	switch val := v.(type) {
	case string:
		e.emitStringScalar(val)
	case yamlRaw:
		e.emitRawPlain(string(val))
	case []string:
		if len(val) == 0 {
			e.writeIndicator("[", true, true, false)
			e.writeIndicator("]", false, false, false)
			e.whitespace = false
			e.indention = false
			return
		}
		e.emitBlockSequence(len(val), func(i int) { e.emitStringScalar(val[i]) })
	case []yamlMapping:
		if len(val) == 0 {
			e.writeIndicator("[", true, true, false)
			e.writeIndicator("]", false, false, false)
			e.whitespace = false
			e.indention = false
			return
		}
		e.emitBlockSequence(len(val), func(i int) { e.emitMapping(val[i]) })
	}
}

func (e *yamlEmitter) emitBlockSequence(n int, item func(i int)) {
	// mapping context, not at line start -> indentless sequence
	indentless := !e.indention
	saved := e.indent
	e.increaseIndent(false, indentless)
	seqIndent := e.indent
	for i := 0; i < n; i++ {
		e.indent = seqIndent
		e.writeIndent()
		e.writeIndicator("-", true, false, true)
		item(i)
	}
	e.indent = saved
}

// MarshalTaskYAML renders the task in the on-disk file format.
func MarshalTaskYAML(t *Task, includeStatus bool) []byte {
	e := newYamlEmitter()
	m := yamlMapping{}
	if includeStatus {
		m = append(m, yamlKV{"status", t.Status})
	}
	tags := t.Tags
	if tags == nil {
		tags = []string{}
	}
	deps := t.Dependencies
	if deps == nil {
		deps = []string{}
	}
	subtasks := []yamlMapping{}
	for _, st := range t.Subtasks {
		subtasks = append(subtasks, yamlMapping{
			{"summary", st.Summary},
			{"resolved", yamlRaw(strconv.FormatBool(st.Resolved))},
		})
	}
	m = append(m,
		yamlKV{"summary", t.Summary},
		yamlKV{"notes", t.Notes},
		yamlKV{"tags", tags},
		yamlKV{"project", t.Project},
		yamlKV{"priority", t.Priority},
		yamlKV{"delegatedto", t.DelegatedTo},
		yamlKV{"subtasks", subtasks},
		yamlKV{"dependencies", deps},
		yamlKV{"created", yamlRaw(t.Created.Format(time.RFC3339Nano))},
		yamlKV{"resolved", yamlRaw(t.Resolved.Format(time.RFC3339Nano))},
		yamlKV{"due", yamlRaw(t.Due.Format(time.RFC3339Nano))},
	)
	e.emitMapping(m)
	// document end
	e.writeIndent()
	return e.buf.Bytes()
}
