package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// A small YAML parser covering the subset of YAML needed for task files:
// block mappings, block sequences, flow sequences/mappings, plain/quoted
// scalars, literal and folded block scalars, comments.

type yKind int

const (
	yScalar yKind = iota
	yMap
	ySeq
)

type yStyle int

const (
	ysPlain yStyle = iota
	ysSingle
	ysDouble
	ysLiteral
	ysFolded
)

type yNode struct {
	kind  yKind
	value string
	style yStyle
	tag   string
	items []*yNode
	keys  []*yNode
	vals  []*yNode
	line  int // 1-based
}

type yamlSyntaxError struct {
	line int
	msg  string
}

func (e *yamlSyntaxError) Error() string {
	return fmt.Sprintf("yaml: line %d: %s", e.line, e.msg)
}

type yLine struct {
	indent  int    // number of leading spaces
	text    string // content after indentation (comments stripped only where relevant)
	raw     string // full raw line
	num     int    // 1-based
	blank   bool   // empty or comment only
}

type yParser struct {
	lines []yLine
	pos   int
}

func yParse(data string) (node *yNode, err error) {
	defer func() {
		if r := recover(); r != nil {
			if se, ok := r.(*yamlSyntaxError); ok {
				node = nil
				err = se
				return
			}
			panic(r)
		}
	}()

	data = strings.ReplaceAll(data, "\r\n", "\n")
	data = strings.ReplaceAll(data, "\r", "\n")
	rawLines := strings.Split(data, "\n")
	if len(rawLines) > 0 && rawLines[len(rawLines)-1] == "" {
		rawLines = rawLines[:len(rawLines)-1]
	}
	p := &yParser{}
	for i, raw := range rawLines {
		l := yLine{raw: raw, num: i + 1}
		j := 0
		for j < len(raw) && raw[j] == ' ' {
			j++
		}
		l.indent = j
		l.text = raw[j:]
		trimmed := strings.TrimSpace(l.text)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			l.blank = true
		}
		if l.text != "" && l.text[0] == '\t' && !l.blank {
			// tabs are not allowed for indentation; treat as content start
		}
		p.lines = append(p.lines, l)
	}

	// skip directives / document start
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.blank {
			p.pos++
			continue
		}
		if l.indent == 0 && strings.HasPrefix(l.text, "%") {
			p.pos++
			continue
		}
		if l.indent == 0 && (l.text == "---" || strings.HasPrefix(l.text, "--- ") || strings.HasPrefix(l.text, "---\t")) {
			rest := strings.TrimSpace(l.text[3:])
			if rest == "" || strings.HasPrefix(rest, "#") {
				p.pos++
				continue
			}
			// inline content after ---
			p.lines[p.pos].text = rest
			p.lines[p.pos].indent = 4
		}
		break
	}

	if p.pos >= len(p.lines) {
		return nil, nil
	}

	node = p.parseBlockNode(-1)
	p.skipBlank()
	if p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent == 0 && (l.text == "..." || l.text == "---" || strings.HasPrefix(l.text, "... ") || strings.HasPrefix(l.text, "--- ")) {
			return node, nil
		}
		panic(&yamlSyntaxError{l.num, "did not find expected <document start>"})
	}
	return node, nil
}

func (p *yParser) skipBlank() {
	for p.pos < len(p.lines) && p.lines[p.pos].blank {
		p.pos++
	}
}

func (p *yParser) cur() *yLine {
	if p.pos < len(p.lines) {
		return &p.lines[p.pos]
	}
	return nil
}

func isDocMarker(l *yLine) bool {
	return l.indent == 0 && (l.text == "---" || l.text == "..." || strings.HasPrefix(l.text, "--- ") || strings.HasPrefix(l.text, "... "))
}

// stripComment removes a trailing comment from inline plain content.
func stripComment(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '#' && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
			return strings.TrimRight(s[:i], " \t")
		}
	}
	return strings.TrimRight(s, " \t")
}

// findMappingColon finds the position of the ": " separator in a plain
// mapping key line, or -1.
func findMappingColon(text string) int {
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c == '#' && (i == 0 || text[i-1] == ' ') {
			return -1
		}
		if c == ':' {
			if i+1 == len(text) || text[i+1] == ' ' || text[i+1] == '\t' {
				return i
			}
		}
		if c == '[' || c == '{' {
			// flow collection start before a colon: not a simple key
			if i == 0 {
				return -1
			}
		}
	}
	return -1
}

// parseQuotedKey parses a quoted key at the start of text, returning the
// key, and the index after the closing quote.
func parseQuotedPrefix(text string, line int) (string, int, yStyle) {
	q := text[0]
	if q == '\'' {
		var sb strings.Builder
		i := 1
		for i < len(text) {
			if text[i] == '\'' {
				if i+1 < len(text) && text[i+1] == '\'' {
					sb.WriteByte('\'')
					i += 2
					continue
				}
				return sb.String(), i + 1, ysSingle
			}
			sb.WriteByte(text[i])
			i++
		}
		panic(&yamlSyntaxError{line, "found unexpected end of stream"})
	}
	// double quoted
	var sb strings.Builder
	i := 1
	for i < len(text) {
		c := text[i]
		if c == '"' {
			return sb.String(), i + 1, ysDouble
		}
		if c == '\\' {
			if i+1 >= len(text) {
				panic(&yamlSyntaxError{line, "found unexpected end of stream"})
			}
			n, w := decodeEscape(text[i+1:], line)
			sb.WriteString(n)
			i += 1 + w
			continue
		}
		sb.WriteByte(c)
		i++
	}
	panic(&yamlSyntaxError{line, "found unexpected end of stream"})
}

func decodeEscape(s string, line int) (string, int) {
	if len(s) == 0 {
		panic(&yamlSyntaxError{line, "found unexpected end of stream"})
	}
	switch s[0] {
	case '0':
		return "\x00", 1
	case 'a':
		return "\a", 1
	case 'b':
		return "\b", 1
	case 't', '\t':
		return "\t", 1
	case 'n':
		return "\n", 1
	case 'v':
		return "\v", 1
	case 'f':
		return "\f", 1
	case 'r':
		return "\r", 1
	case 'e':
		return "\x1b", 1
	case ' ':
		return " ", 1
	case '"':
		return "\"", 1
	case '/':
		return "/", 1
	case '\'':
		return "'", 1
	case '\\':
		return "\\", 1
	case 'N':
		return "\u0085", 1
	case '_':
		return "\u00a0", 1
	case 'L':
		return "\u2028", 1
	case 'P':
		return "\u2029", 1
	case 'x', 'u', 'U':
		var n int
		switch s[0] {
		case 'x':
			n = 2
		case 'u':
			n = 4
		default:
			n = 8
		}
		if len(s) < 1+n {
			panic(&yamlSyntaxError{line, "did not find expected hexdecimal number"})
		}
		v, err := strconv.ParseUint(s[1:1+n], 16, 32)
		if err != nil {
			panic(&yamlSyntaxError{line, "did not find expected hexdecimal number"})
		}
		r := rune(v)
		if !utf8.ValidRune(r) {
			panic(&yamlSyntaxError{line, "found invalid Unicode character escape code"})
		}
		return string(r), 1 + n
	}
	panic(&yamlSyntaxError{line, "found unknown escape character"})
}

// parseBlockNode parses a node whose first line is the current line and
// whose indentation must be greater than parentIndent.
func (p *yParser) parseBlockNode(parentIndent int) *yNode {
	p.skipBlank()
	l := p.cur()
	if l == nil || l.indent <= parentIndent || isDocMarker(l) {
		return &yNode{kind: yScalar, style: ysPlain, value: "", line: p.lineNumOrLast()}
	}
	text := l.text
	if text == "-" || strings.HasPrefix(text, "- ") || strings.HasPrefix(text, "-\t") {
		return p.parseBlockSequence(l.indent)
	}
	if isMappingLine(text, l.num) {
		return p.parseBlockMapping(l.indent)
	}
	return p.parseInlineValue(l.indent, parentIndent, text, l.num, false)
}

func (p *yParser) lineNumOrLast() int {
	if p.pos < len(p.lines) {
		return p.lines[p.pos].num
	}
	if len(p.lines) > 0 {
		return p.lines[len(p.lines)-1].num + 1
	}
	return 1
}

// isMappingLine decides whether a line starts a mapping entry.
func isMappingLine(text string, line int) bool {
	if text == "" {
		return false
	}
	switch text[0] {
	case '"', '\'':
		_, end, _ := parseQuotedPrefix(text, line)
		rest := text[end:]
		rest = strings.TrimLeft(rest, " \t")
		return strings.HasPrefix(rest, ":") && (len(rest) == 1 || rest[1] == ' ' || rest[1] == '\t')
	case '[', '{', '|', '>', '#':
		return false
	case '?':
		if len(text) == 1 || text[1] == ' ' {
			return true
		}
	}
	return findMappingColon(text) >= 0
}

func (p *yParser) parseBlockSequence(indent int) *yNode {
	node := &yNode{kind: ySeq, line: p.cur().num}
	for {
		p.skipBlank()
		l := p.cur()
		if l == nil || isDocMarker(l) {
			break
		}
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			panic(&yamlSyntaxError{l.num, "did not find expected '-' indicator"})
		}
		text := l.text
		if !(text == "-" || strings.HasPrefix(text, "- ") || strings.HasPrefix(text, "-\t")) {
			// something else at the same indentation: end of the sequence
			// if we are inside a mapping (indentless), else error
			break
		}
		rest := ""
		if len(text) > 1 {
			rest = text[2:]
		}
		restTrim := strings.TrimLeft(rest, " \t")
		if restTrim == "" || strings.HasPrefix(restTrim, "#") {
			// nested node on following lines
			p.pos++
			node.items = append(node.items, p.parseBlockNode(indent))
			continue
		}
		// inline content: compute its column
		col := indent + 2 + (len(rest) - len(restTrim))
		// rewrite the current line as if it started at col
		saved := *l
		l.indent = col
		l.text = restTrim
		var item *yNode
		if restTrim == "-" || strings.HasPrefix(restTrim, "- ") {
			item = p.parseBlockSequence(col)
		} else if isMappingLine(restTrim, l.num) {
			item = p.parseBlockMapping(col)
		} else {
			item = p.parseInlineValue(col, indent, restTrim, l.num, false)
		}
		// restore (the line pointer may have advanced; restore only if same line object)
		if p.pos < len(p.lines) && &p.lines[p.pos] == l {
			*l = saved
		} else {
			*l = saved
		}
		node.items = append(node.items, item)
	}
	return node
}

func (p *yParser) parseBlockMapping(indent int) *yNode {
	node := &yNode{kind: yMap, line: p.cur().num}
	for {
		p.skipBlank()
		l := p.cur()
		if l == nil || isDocMarker(l) {
			break
		}
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			panic(&yamlSyntaxError{l.num, "did not find expected key"})
		}
		text := l.text
		if text == "-" || strings.HasPrefix(text, "- ") {
			panic(&yamlSyntaxError{l.num, "did not find expected key"})
		}
		// parse the key
		var key *yNode
		var rest string
		if text[0] == '"' || text[0] == '\'' {
			k, end, st := parseQuotedPrefix(text, l.num)
			key = &yNode{kind: yScalar, value: k, style: st, line: l.num}
			after := strings.TrimLeft(text[end:], " \t")
			if !strings.HasPrefix(after, ":") {
				panic(&yamlSyntaxError{l.num, "could not find expected ':'"})
			}
			rest = after[1:]
		} else if text == "?" || strings.HasPrefix(text, "? ") {
			panic(&yamlSyntaxError{l.num, "complex keys are not supported"})
		} else {
			ci := findMappingColon(text)
			if ci < 0 {
				panic(&yamlSyntaxError{l.num, "could not find expected ':'"})
			}
			k := strings.TrimRight(text[:ci], " \t")
			key = &yNode{kind: yScalar, value: k, style: ysPlain, line: l.num}
			rest = text[ci+1:]
		}
		restTrim := strings.TrimLeft(rest, " \t")
		var val *yNode
		if restTrim == "" || strings.HasPrefix(restTrim, "#") {
			// value on following lines (or null)
			p.pos++
			p.skipBlank()
			nl := p.cur()
			if nl == nil || isDocMarker(nl) || nl.indent < indent {
				val = &yNode{kind: yScalar, style: ysPlain, value: "", line: l.num}
			} else if nl.indent == indent {
				if nl.text == "-" || strings.HasPrefix(nl.text, "- ") || strings.HasPrefix(nl.text, "-\t") {
					val = p.parseBlockSequence(indent)
				} else {
					val = &yNode{kind: yScalar, style: ysPlain, value: "", line: l.num}
				}
			} else {
				val = p.parseBlockNode(indent)
			}
		} else {
			val = p.parseInlineValue(indent+1, indent, restTrim, l.num, true)
		}
		node.keys = append(node.keys, key)
		node.vals = append(node.vals, val)
	}
	return node
}

// parseInlineValue parses a value which starts with the given text on the
// current line (which is then consumed). Continuation lines must be
// indented more than parentIndent.
func (p *yParser) parseInlineValue(col, parentIndent int, text string, lineNum int, afterKey bool) *yNode {
	switch text[0] {
	case '|', '>':
		return p.parseBlockScalar(parentIndent, text, lineNum)
	case '"', '\'':
		return p.parseQuotedScalar(parentIndent, text, lineNum)
	case '[', '{':
		return p.parseFlow(parentIndent, text, lineNum)
	case '!':
		// tag: strip and parse the rest
		sp := strings.IndexAny(text, " \t")
		tag := text
		rest := ""
		if sp >= 0 {
			tag = text[:sp]
			rest = strings.TrimLeft(text[sp:], " \t")
		}
		if rest == "" {
			p.pos++
			n := p.parseBlockNode(parentIndent)
			n.tag = tag
			return n
		}
		n := p.parseInlineValue(col, parentIndent, rest, lineNum, afterKey)
		n.tag = tag
		return n
	case '&', '*':
		panic(&yamlSyntaxError{lineNum, "anchors and aliases are not supported"})
	case '%':
		panic(&yamlSyntaxError{lineNum, "found character that cannot start any token"})
	case '@', '`':
		panic(&yamlSyntaxError{lineNum, "found character that cannot start any token"})
	}
	// plain scalar, possibly multi-line
	if afterKey {
		if ci := findMappingColon(text); ci >= 0 {
			panic(&yamlSyntaxError{lineNum, "mapping values are not allowed in this context"})
		}
	}
	first := stripComment(text)
	p.pos++
	var parts []string
	parts = append(parts, first)
	hadComment := strings.Contains(text, " #") || strings.HasPrefix(text, "#")
	if !hadComment {
		for p.pos < len(p.lines) {
			l := &p.lines[p.pos]
			if l.blank {
				if strings.TrimSpace(l.text) != "" {
					// comment line ends the scalar
					break
				}
				parts = append(parts, "")
				p.pos++
				continue
			}
			if l.indent <= parentIndent || isDocMarker(l) {
				break
			}
			if findMappingColon(l.text) >= 0 {
				panic(&yamlSyntaxError{l.num, "mapping values are not allowed in this context"})
			}
			if l.text == "-" || strings.HasPrefix(l.text, "- ") {
				break
			}
			t := l.text
			if ci := strings.Index(t, " #"); ci >= 0 {
				t = strings.TrimRight(t[:ci], " \t")
				parts = append(parts, t)
				p.pos++
				break
			}
			parts = append(parts, strings.TrimRight(t, " \t"))
			p.pos++
		}
	}
	// trailing blank lines are not part of the scalar
	for len(parts) > 1 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	// rewind over trailing blank lines we consumed is unnecessary (blank)
	return &yNode{kind: yScalar, style: ysPlain, value: foldLines(parts), line: lineNum}
}

// foldLines folds plain scalar continuation lines: single line breaks
// become spaces, empty lines become newlines.
func foldLines(parts []string) string {
	var sb strings.Builder
	sb.WriteString(parts[0])
	i := 1
	for i < len(parts) {
		if parts[i] == "" {
			n := 0
			for i < len(parts) && parts[i] == "" {
				n++
				i++
			}
			sb.WriteString(strings.Repeat("\n", n))
			if i < len(parts) {
				sb.WriteString(parts[i])
				i++
			}
			continue
		}
		sb.WriteByte(' ')
		sb.WriteString(parts[i])
		i++
	}
	return sb.String()
}

func (p *yParser) parseQuotedScalar(parentIndent int, text string, lineNum int) *yNode {
	q := text[0]
	// gather the full quoted text, possibly over several lines
	var sb strings.Builder
	cur := text
	curLine := lineNum
	firstLine := true
	for {
		// scan cur for closing quote
		i := 1
		if !firstLine {
			i = 0
		}
		closed := false
		for i < len(cur) {
			c := cur[i]
			if q == '\'' {
				if c == '\'' {
					if i+1 < len(cur) && cur[i+1] == '\'' {
						sb.WriteByte('\'')
						i += 2
						continue
					}
					closed = true
					i++
					break
				}
				sb.WriteByte(c)
				i++
				continue
			}
			// double quoted
			if c == '"' {
				closed = true
				i++
				break
			}
			if c == '\\' {
				if i+1 >= len(cur) {
					// escaped line break: join without space
					i++
					sb.WriteString("\x00ESCBREAK")
					break
				}
				n, w := decodeEscape(cur[i+1:], curLine)
				sb.WriteString(n)
				i += 1 + w
				continue
			}
			sb.WriteByte(c)
			i++
		}
		if closed {
			rest := strings.TrimLeft(cur[i:], " \t")
			if rest != "" && !strings.HasPrefix(rest, "#") {
				if strings.HasPrefix(rest, ":") {
					panic(&yamlSyntaxError{curLine, "mapping values are not allowed in this context"})
				}
				panic(&yamlSyntaxError{curLine, "did not find expected <document start>"})
			}
			p.pos++
			break
		}
		// continue on next line
		p.pos++
		if p.pos >= len(p.lines) {
			panic(&yamlSyntaxError{curLine, "found unexpected end of stream"})
		}
		nl := p.lines[p.pos]
		if isDocMarker(&nl) {
			panic(&yamlSyntaxError{nl.num, "found unexpected document indicator"})
		}
		cur = strings.TrimLeft(nl.raw, " \t")
		curLine = nl.num
		firstLine = false
		// line folding
		s := sb.String()
		if strings.HasSuffix(s, "\x00ESCBREAK") {
			sb.Reset()
			sb.WriteString(strings.TrimSuffix(s, "\x00ESCBREAK"))
		} else {
			trimmed := strings.TrimRight(s, " \t")
			sb.Reset()
			sb.WriteString(trimmed)
			if cur == "" {
				sb.WriteByte('\n')
				// consume following empty lines as newlines
				for p.pos+1 < len(p.lines) && strings.TrimSpace(p.lines[p.pos+1].raw) == "" {
					sb.WriteByte('\n')
					p.pos++
				}
				continue
			}
			sb.WriteByte(' ')
		}
	}
	st := ysSingle
	if q == '"' {
		st = ysDouble
	}
	return &yNode{kind: yScalar, style: st, value: sb.String(), line: lineNum}
}

func (p *yParser) parseBlockScalar(parentIndent int, header string, lineNum int) *yNode {
	style := ysLiteral
	if header[0] == '>' {
		style = ysFolded
	}
	chomp := byte(0) // 0 clip, '-' strip, '+' keep
	explicitIndent := 0
	i := 1
	for i < len(header) {
		c := header[i]
		if c == '-' || c == '+' {
			if chomp != 0 {
				panic(&yamlSyntaxError{lineNum, "found unexpected chomping indicator"})
			}
			chomp = c
		} else if c >= '1' && c <= '9' {
			if explicitIndent != 0 {
				panic(&yamlSyntaxError{lineNum, "found unexpected indentation indicator"})
			}
			explicitIndent = int(c - '0')
		} else {
			break
		}
		i++
	}
	rest := strings.TrimLeft(header[i:], " \t")
	if rest != "" && !strings.HasPrefix(rest, "#") {
		panic(&yamlSyntaxError{lineNum, "did not find expected comment or line break"})
	}
	p.pos++

	base := parentIndent
	if base < 0 {
		base = 0
	}
	var indent int
	if explicitIndent > 0 {
		indent = base + explicitIndent
	} else {
		indent = -1
	}

	var lines []string
	var trailingBreaks int
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		raw := l.raw
		if strings.TrimSpace(raw) == "" {
			// empty line (within or trailing)
			if indent < 0 {
				// leading empty lines: count spaces to detect max indentation
				lines = append(lines, "")
			} else {
				if len(raw) > indent {
					lines = append(lines, raw[indent:])
				} else {
					lines = append(lines, "")
				}
			}
			p.pos++
			continue
		}
		if isDocMarker(&l) {
			break
		}
		if indent < 0 {
			if l.indent <= base && !(parentIndent < 0 && l.indent == 0 && base == 0 && len(lines) == 0 && false) {
				if l.indent <= parentIndent {
					break
				}
			}
			if l.indent <= parentIndent {
				break
			}
			indent = l.indent
			// re-check leading empty lines had less indentation than indent
		}
		if l.indent < indent {
			break
		}
		lines = append(lines, raw[indent:])
		p.pos++
	}
	// separate trailing empty lines
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailingBreaks++
	}

	var sb strings.Builder
	if style == ysLiteral {
		for idx, ln := range lines {
			sb.WriteString(ln)
			if idx < len(lines)-1 {
				sb.WriteByte('\n')
			}
		}
	} else {
		// folded
		for idx := 0; idx < len(lines); idx++ {
			ln := lines[idx]
			sb.WriteString(ln)
			if idx == len(lines)-1 {
				break
			}
			next := lines[idx+1]
			moreIndented := func(s string) bool { return len(s) > 0 && (s[0] == ' ' || s[0] == '\t') }
			if ln == "" {
				sb.WriteByte('\n')
			} else if next == "" || moreIndented(ln) || moreIndented(next) {
				sb.WriteByte('\n')
			} else {
				sb.WriteByte(' ')
			}
		}
	}
	value := sb.String()
	if len(lines) > 0 {
		switch chomp {
		case '-':
		case '+':
			value += strings.Repeat("\n", trailingBreaks+1)
		default:
			value += "\n"
		}
	} else {
		if chomp == '+' {
			value = strings.Repeat("\n", trailingBreaks)
		}
	}
	return &yNode{kind: yScalar, style: style, value: value, line: lineNum}
}

// parseFlow parses a flow collection starting at text on the current line,
// possibly continuing over following lines.
func (p *yParser) parseFlow(parentIndent int, text string, lineNum int) *yNode {
	fp := &flowParser{p: p, s: text, line: lineNum}
	n := fp.parseValue()
	fp.skipSpace()
	if fp.i < len(fp.s) {
		rest := fp.s[fp.i:]
		if !strings.HasPrefix(rest, "#") {
			if strings.HasPrefix(rest, ":") {
				panic(&yamlSyntaxError{fp.line, "mapping values are not allowed in this context"})
			}
			panic(&yamlSyntaxError{fp.line, "did not find expected <document start>"})
		}
	}
	p.pos++
	return n
}

type flowParser struct {
	p    *yParser
	s    string
	i    int
	line int
}

// more pulls in the next line when the flow collection continues.
func (f *flowParser) more() bool {
	if f.p.pos+1 >= len(f.p.lines) {
		return false
	}
	f.p.pos++
	l := f.p.lines[f.p.pos]
	f.s = f.s[f.i:] + "\n" + l.raw
	f.i = 0
	f.line = l.num
	return true
}

func (f *flowParser) skipSpace() {
	for {
		for f.i < len(f.s) && (f.s[f.i] == ' ' || f.s[f.i] == '\t' || f.s[f.i] == '\n') {
			if f.s[f.i] == '\n' {
				f.line++
			}
			f.i++
		}
		if f.i < len(f.s) && f.s[f.i] == '#' {
			for f.i < len(f.s) && f.s[f.i] != '\n' {
				f.i++
			}
			continue
		}
		if f.i >= len(f.s) {
			if !f.more() {
				return
			}
			f.line--
			continue
		}
		return
	}
}

func (f *flowParser) parseValue() *yNode {
	f.skipSpace()
	if f.i >= len(f.s) {
		panic(&yamlSyntaxError{f.line, "found unexpected end of stream"})
	}
	c := f.s[f.i]
	switch c {
	case '[':
		f.i++
		node := &yNode{kind: ySeq, line: f.line}
		for {
			f.skipSpace()
			if f.i >= len(f.s) {
				panic(&yamlSyntaxError{f.line, "did not find expected ',' or ']'"})
			}
			if f.s[f.i] == ']' {
				f.i++
				return node
			}
			if len(node.items) > 0 {
				if f.s[f.i] != ',' {
					panic(&yamlSyntaxError{f.line, "did not find expected ',' or ']'"})
				}
				f.i++
				f.skipSpace()
				if f.i < len(f.s) && f.s[f.i] == ']' {
					f.i++
					return node
				}
			}
			item := f.parseValue()
			// single pair mapping inside a sequence: "key: value"
			f.skipSpace()
			if f.i < len(f.s) && f.s[f.i] == ':' && item.kind == yScalar {
				f.i++
				v := f.parseValue()
				m := &yNode{kind: yMap, line: item.line}
				m.keys = append(m.keys, item)
				m.vals = append(m.vals, v)
				item = m
			}
			node.items = append(node.items, item)
		}
	case '{':
		f.i++
		node := &yNode{kind: yMap, line: f.line}
		for {
			f.skipSpace()
			if f.i >= len(f.s) {
				panic(&yamlSyntaxError{f.line, "did not find expected ',' or '}'"})
			}
			if f.s[f.i] == '}' {
				f.i++
				return node
			}
			if len(node.keys) > 0 {
				if f.s[f.i] != ',' {
					panic(&yamlSyntaxError{f.line, "did not find expected ',' or '}'"})
				}
				f.i++
				f.skipSpace()
				if f.i < len(f.s) && f.s[f.i] == '}' {
					f.i++
					return node
				}
			}
			key := f.parseValue()
			f.skipSpace()
			var val *yNode
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				f.skipSpace()
				if f.i < len(f.s) && (f.s[f.i] == ',' || f.s[f.i] == '}') {
					val = &yNode{kind: yScalar, style: ysPlain, value: "", line: f.line}
				} else {
					val = f.parseValue()
				}
			} else {
				val = &yNode{kind: yScalar, style: ysPlain, value: "", line: f.line}
			}
			node.keys = append(node.keys, key)
			node.vals = append(node.vals, val)
		}
	case '"', '\'':
		// quoted scalar within flow context (single line only, or joined)
		for {
			rest := f.s[f.i:]
			end := findClosingQuote(rest)
			if end < 0 {
				if !f.more() {
					panic(&yamlSyntaxError{f.line, "found unexpected end of stream"})
				}
				continue
			}
			v, _, st := parseQuotedPrefix(rest[:end+1], f.line)
			f.i += end + 1
			return &yNode{kind: yScalar, style: st, value: v, line: f.line}
		}
	}
	// plain scalar in flow context
	start := f.i
	for f.i < len(f.s) {
		c := f.s[f.i]
		if c == ',' || c == ']' || c == '}' || c == '\n' {
			break
		}
		if c == '[' || c == '{' {
			break
		}
		if c == ':' && (f.i+1 >= len(f.s) || f.s[f.i+1] == ' ' || f.s[f.i+1] == ',' || f.s[f.i+1] == ']' || f.s[f.i+1] == '}') {
			break
		}
		if c == '#' && f.i > start && f.s[f.i-1] == ' ' {
			break
		}
		f.i++
	}
	v := strings.TrimRight(f.s[start:f.i], " \t")
	if v == "" {
		panic(&yamlSyntaxError{f.line, "found unexpected ':'"})
	}
	return &yNode{kind: yScalar, style: ysPlain, value: v, line: f.line}
}

func findClosingQuote(s string) int {
	q := s[0]
	i := 1
	for i < len(s) {
		if q == '\'' {
			if s[i] == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i += 2
					continue
				}
				return i
			}
			i++
			continue
		}
		if s[i] == '\\' {
			i += 2
			continue
		}
		if s[i] == '"' {
			return i
		}
		i++
	}
	return -1
}
