{"command":"cd /workspace/src && cat > yamldecode.go <<'EOF'
package main

import (
	"fmt"
	"strings"
	"time"
)

// yamlTypeError mirrors yaml.v2's TypeError formatting.
type yamlTypeError struct {
	errors []string
}

func (e *yamlTypeError) Error() string {
	return fmt.Sprintf("yaml: unmarshal errors:\n  %s", strings.Join(e.errors, "\n  "))
}

type yDecoder struct {
	terrors []string
}

func shortTagFor(n *yNode) string {
	if n.tag != "" {
		t := n.tag
		if strings.HasPrefix(t, "!!") {
			return t
		}
		return t
	}
	switch n.kind {
	case ySeq:
		return "!!seq"
	case yMap:
		return "!!map"
	}
	if n.style != ysPlain {
		return "!!str"
	}
	_, tag := yamlResolvePlain(n.value)
	return tag
}

func (d *yDecoder) terror(n *yNode, typ string) {
	tag := shortTagFor(n)
	value := n.value
	if tag != "!!seq" && tag != "!!map" {
		if len(value) > 10 {
			value = " `" + value[:7] + "...`"
		} else {
			value = " `" + value + "`"
		}
	} else {
		value = ""
	}
	d.terrors = append(d.terrors, fmt.Sprintf("line %d: cannot unmarshal %s%s into %s", n.line, tag, value, typ))
}

// resolved returns the resolved value of a scalar node (nil for null).
func resolvedValue(n *yNode) (interface{}, string) {
	if n.style != ysPlain || (n.tag != "" && n.tag != "!!null") {
		if n.tag == "!!null" {
			return nil, "!!null"
		}
		return n.value, "!!str"
	}
	return yamlResolvePlain(n.value)
}

func (d *yDecoder) decodeString(n *yNode, out *string) {
	if n.kind != yScalar {
		d.terror(n, "string")
		return
	}
	v, _ := resolvedValue(n)
	if v == nil {
		*out = ""
		return
	}
	*out = n.value
}

func (d *yDecoder) decodeBool(n *yNode, out *bool) {
	if n.kind != yScalar {
		d.terror(n, "bool")
		return
	}
	v, _ := resolvedValue(n)
	if v == nil {
		*out = false
		return
	}
	if b, ok := v.(bool); ok {
		*out = b
		return
	}
	d.terror(n, "bool")
}

func (d *yDecoder) decodeStringSlice(n *yNode, out *[]string) error {
	if n.kind == yScalar {
		v, _ := resolvedValue(n)
		if v == nil {
			*out = nil
			return nil
		}
		d.terror(n, "[]string")
		return nil
	}
	if n.kind == yMap {
		d.terror(n, "[]string")
		return nil
	}
	res := make([]string, 0, len(n.items))
	for _, item := range n.items {
		var s string
		d.decodeString(item, &s)
		res = append(res, s)
	}
	*out = res
	return nil
}

func (d *yDecoder) decodeTime(n *yNode, out *time.Time) error {
	if n.kind != yScalar {
		d.terror(n, "time.Time")
		return nil
	}
	v, _ := resolvedValue(n)
	if v == nil {
		*out = time.Time{}
		return nil
	}
	if t, ok := v.(time.Time); ok {
		*out = t
		return nil
	}
	// fall back to TextUnmarshaler behaviour (RFC3339)
	var t time.Time
	if err := t.UnmarshalText([]byte(n.value)); err != nil {
		return err
	}
	*out = t
	return nil
}

func (d *yDecoder) decodeSubtasks(n *yNode, out *[]SubTask) {
	if n.kind == yScalar {
		v, _ := resolvedValue(n)
		if v == nil {
			*out = nil
			return
		}
		d.terror(n, "[]dstask.SubTask")
		return
	}
	if n.kind == yMap {
		d.terror(n, "[]dstask.SubTask")
		return
	}
	res := make([]SubTask, 0, len(n.items))
	for _, item := range n.items {
		var st SubTask
		if item.kind == yScalar {
			v, _ := resolvedValue(item)
			if v != nil {
				d.terror(item, "dstask.SubTask")
			}
			res = append(res, st)
			continue
		}
		if item.kind == ySeq {
			d.terror(item, "dstask.SubTask")
			res = append(res, st)
			continue
		}
		for i, k := range item.keys {
			var key string
			if k.kind != yScalar {
				continue
			}
			key = k.value
			switch strings.ToLower(key) {
			case "summary":
				d.decodeString(item.vals[i], &st.Summary)
			case "resolved":
				d.decodeBool(item.vals[i], &st.Resolved)
			}
		}
		res = append(res, st)
	}
	*out = res
}

// UnmarshalTaskYAML decodes YAML into an existing task. If allowStatus is
// set, a "status" key is honoured.
func UnmarshalTaskYAML(data []byte, t *Task, allowStatus bool) error {
	root, err := yParse(string(data))
	if err != nil {
		return err
	}
	if root == nil {
		return nil
	}
	d := &yDecoder{}
	if root.kind != yMap {
		if root.kind == yScalar {
			v, _ := resolvedValue(root)
			if v == nil {
				return nil
			}
		}
		d.terror(root, "dstask.Task")
		return &yamlTypeError{d.terrors}
	}
	for i, k := range root.keys {
		if k.kind != yScalar {
			continue
		}
		val := root.vals[i]
		switch k.value {
		case "status":
			if allowStatus {
				d.decodeString(val, &t.Status)
			}
		case "summary":
			d.decodeString(val, &t.Summary)
		case "notes":
			d.decodeString(val, &t.Notes)
		case "tags":
			d.decodeStringSlice(val, &t.Tags)
		case "project":
			d.decodeString(val, &t.Project)
		case "priority":
			d.decodeString(val, &t.Priority)
		case "delegatedto":
			d.decodeString(val, &t.DelegatedTo)
		case "subtasks":
			d.decodeSubtasks(val, &t.Subtasks)
		case "dependencies":
			d.decodeStringSlice(val, &t.Dependencies)
		case "created":
			if err := d.decodeTime(val, &t.Created); err != nil {
				return err
			}
		case "resolved":
			if err := d.decodeTime(val, &t.Resolved); err != nil {
				return err
			}
		case "due":
			if err := d.decodeTime(val, &t.Due); err != nil {
				return err
			}
		}
	}
	if len(d.terrors) > 0 {
