package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

// MustRunGitCmd runs git inside the repository with inherited stdio.
func MustRunGitCmd(repoPath string, args ...string) {
	fullArgs := append([]string{"-C", repoPath}, args...)
	if err := RunCmdInteractive("git", fullArgs...); err != nil {
		ExitFail("Failed to run git cmd.")
	}
}

// runGitCaptured runs git, printing its stdout to our stdout and its stderr
// to our stderr after completion. Returns the exit error, if any.
func runGitCaptured(repoPath string, args ...string) error {
	fullArgs := append([]string{"-C", repoPath}, args...)
	cmd := exec.Command("git", fullArgs...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	os.Stderr.Write(stderr.Bytes())
	os.Stdout.Write(stdout.Bytes())
	return err
}

// gitRepoHasObjects reports whether the object store holds anything beyond
// the default info/pack directories (used to decide whether a diff against
// HEAD is meaningful).
func gitRepoHasObjects(repoPath string) bool {
	entries, err := os.ReadDir(filepath.Join(repoPath, ".git", "objects"))
	if err != nil {
		return false
	}
	return len(entries) > 2
}

// MustGitCommit stages everything and commits with the given message,
// printing progress in grey.
func MustGitCommit(repoPath string, format string, a ...interface{}) {
	msg := fmt.Sprintf(format, a...)
	fmt.Printf("\n%s\n", msg)
	fmt.Printf("\033[38;5;%dm", ColFgGrey)

	if err := runGitCaptured(repoPath, "add", "."); err != nil {
		ExitFail("error: failed to add changes: %s", err)
	}

	if gitRepoHasObjects(repoPath) {
		if err := runGitCaptured(repoPath, "diff-index", "--quiet", "HEAD", "--"); err == nil {
			fmt.Println("No changes detected")
			fmt.Print("\033[0m")
			return
		}
	}

	if err := runGitCaptured(repoPath, "commit", "--no-gpg-sign", "-m", msg); err != nil {
		ExitFail("error: failed to commit changes: %s", err)
	}
	fmt.Print("\033[0m")
}

// EnsureRepoExists creates and initialises the repository if required.
func EnsureRepoExists(repoPath string) {
	if fileExists(filepath.Join(repoPath, ".git")) {
		return
	}

	if StdoutIsTTY() {
		ConfirmOrAbort("Could not find dstask repository at %s -- create?", repoPath)
	}

	if err := os.Mkdir(repoPath, 0700); err != nil {
		ExitFail("Failed to create directory in git repository")
	}

	MustRunGitCmd(repoPath, "init")
	fmt.Printf("\nAdd a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n")
}
