// LoadTaskSet reads tasks from disk. Resolved tasks are only loaded when
// requested.
func LoadTaskSet(repoPath, idsFile string, includeResolved bool) *TaskSet {
	ts := &TaskSet{
		tasksByID:   make(map[int]*Task),
		tasksByUUID: make(map[string]*Task),
		repoPath:    repoPath,
		idsFile:     idsFile,
		ids:         LoadIds(idsFile),
	}

	for _, status := range AllStatuses {
		if status == StatusResolved && !includeResolved {
			continue
		}
		dir := filepath.Join(repoPath, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, entry := range entries {
			name := entry.Name()
			if entry.IsDir() || !strings.HasSuffix(name, ".yml") {
				continue
			}
			uuid := strings.TrimSuffix(name, ".yml")
			if !IsValidUUID4String(uuid) {
				continue
			}
			path := filepath.Join(dir, name)
			data, err := os.ReadFile(path)
			if err != nil {
				ExitFail("Failed to read %s", path)
			}
			task := &Task{UUID: uuid, Status: status}
			if err := UnmarshalTaskYAML(data, task, false); err != nil {
				ExitFail("Failed to unmarshal %s: %s", path, err)
			}
			if status != StatusResolved {
				task.ID = ts.ids[uuid]
			}
			ts.loadTask(task)
		}
	}

	ts.assignIDs()
	return ts
}

func (ts *TaskSet) loadTask(task *Task) {
	task.Normalise()
	if task.ID > 0 {
		if _, exists := ts.tasksByID[task.ID]; exists {
			// duplicate ID -- reassign later
			task.ID = 0
		} else {
			ts.tasksByID[task.ID] = task
		}
	}
	ts.tasksByUUID[task.UUID] = task
	ts.tasks = append(ts.tasks, task)
}

// assignIDs gives the lowest available IDs to non-resolved tasks without one.
func (ts *TaskSet) assignIDs() {
	next := 1
	for _, task := range ts.tasks {
		if task.Status == StatusResolved || task.ID > 0 {
			continue
		}
		for ts.tasksByID[next] != nil {
			next++
		}
		task.ID = next
		ts.tasksByID[next] = task
	}
}

// AddTask registers a freshly created task.
func (ts *TaskSet) AddTask(task Task) *Task {
	if task.UUID == "" {
		task.UUID = MustGetUUID4String()
	}
	if task.Created.IsZero() {
		task.Created = time.Now()
	}
	if task.Status == "" {
		task.Status = StatusPending
	}
	if task.Priority == "" {
		task.Priority = PriorityNormal
	}
	task.writePending = true
	t := &task
	ts.loadTask(t)
	if t.Status != StatusResolved && t.ID == 0 {
		ts.assignIDs()
	}
	return t
}

// AllTasks returns every loaded task.
func (ts *TaskSet) AllTasks() Tasks {
	return ts.tasks
}

// MustGetByID returns the non-resolved task with the given ID or exits.
func (ts *TaskSet) MustGetByID(id int) *Task {
	task, ok := ts.tasksByID[id]
	if !ok || task.Status == StatusResolved {
		ExitFail("no open task with ID %d exists", id)
	}
	return task
}

// MustUpdateTask marks a task as needing to be written.
func (ts *TaskSet) MustUpdateTask(task *Task) {
	if err := task.Validate(); err != nil {
		ExitFail("%s, task %s", err.Error(), task.UUID)
	}
	task.writePending = true
	if task.Status == StatusResolved {
		if task.Resolved.IsZero() {
			task.Resolved = time.Now()
		}
		if task.ID > 0 {
			delete(ts.tasksByID, task.ID)
		}
		task.ID = 0
	}
}

// RemoveTask deletes the task file on save.
func (ts *TaskSet) RemoveTask(task *Task) {
	task.deleted = true
	task.writePending = true
}

// SavePendingChanges writes modified tasks and the ID map to disk.
func (ts *TaskSet) SavePendingChanges() {
	for _, task := range ts.tasks {
		if !task.writePending {
			continue
		}
		// remove files from any other status directory
		for _, status := range AllStatuses {
			if status == task.Status && !task.deleted {
				continue
			}
			path := filepath.Join(ts.repoPath, status, task.UUID+".yml")
			if fileExists(path) {
				if err := os.Remove(path); err != nil {
					ExitFail("Failed to remove %s", path)
				}
			}
		}
		if task.deleted {
			continue
		}
		task.Normalise()
		dir := filepath.Join(ts.repoPath, task.Status)
		if err := os.MkdirAll(dir, 0700); err != nil {
			ExitFail("Failed to create directory %s", dir)
		}
		path := filepath.Join(dir, task.UUID+".yml")
		data := MarshalTaskYAML(task, false)
		if err := os.WriteFile(path, data, 0600); err != nil {
			ExitFail("Failed to write %s", path)
		}
		task.writePending = false
	}

	ids := make(IdsMap)
	for _, task := range ts.tasks {
		if task.ID > 0 && task.Status != StatusResolved {
			ids[task.UUID] = task.ID
		}
	}
	ids.Save(ts.idsFile)
}

