	t.Styles = append(t.Styles, style)
}

func (t *Table) AddStringRow(style RowStyle, cells ...string) {
	row := make([]Cell, len(cells))
	for i, c := range cells {
		row[i] = Cell{Text: c}
	}
	t.AddRow(style, row...)
}

func (c Cell) full() string {
	if c.Note != "" {
		return c.Text + " " + c.Note
	}
	return c.Text
}

func (c Cell) naturalWidth() int {
	if c.Note != "" {
		return StringWidth(c.full()) + 2
	}
	return StringWidth(c.Text)
}

// columnWidths computes the column widths, shrinking the widest columns
// until the table fits.
func (t *Table) columnWidths() []int {
	ncols := len(t.Header)
	widths := make([]int, ncols)
	for i, h := range t.Header {
		widths[i] = StringWidth(h)
	}
	for _, row := range t.Rows {
		for i := 0; i < ncols && i < len(row); i++ {
			if w := row[i].naturalWidth(); w > widths[i] {
				widths[i] = w
			}
		}
	}
	total := 2 * (ncols - 1)
	for _, w := range widths {
		total += w
	}
	for total > t.Width {
		maxIdx := 0
		for i, w := range widths {
			if w > widths[maxIdx] {
				maxIdx = i
			}
		}
		if widths[maxIdx] <= 0 {
			break
		}
		widths[maxIdx]--
		total--
	}
	return widths
}

func fitCell(s string, w int) string {
	if StringWidth(s) > w {
		return Truncate(s, w, " ")
	}
	return FillRight(s, w)
}

func renderCell(c Cell, w int, fg int) string {
	full := c.full()
	out := fitCell(full, w)
	if c.Note != "" && len(out) > len(c.Text) && strings.HasPrefix(out, c.Text) {
		tail := out[len(c.Text):]
		if strings.TrimSpace(tail) != "" {
			return c.Text + fmt.Sprintf("\033[38;5;%dm", ColFgNote) + tail + fmt.Sprintf("\033[38;5;%dm", fg)
		}
	}
	return out
}

// Render returns the table as a string of coloured lines.
func (t *Table) Render() string {
	widths := t.columnWidths()
	var sb strings.Builder

	headerCells := make([]string, len(t.Header))
	for i, h := range t.Header {
		headerCells[i] = fitCell(h, widths[i])
	}
	sb.WriteString(fmt.Sprintf("\033[%d;38;5;%d;48;5;%dm%s\033[0m\n", ModeHeader, ColFgDefault, ColBgDefault2, strings.Join(headerCells, "  ")))

	for r, row := range t.Rows {
		style := t.Styles[r]
		cells := make([]string, len(t.Header))
		for i := range t.Header {
			var c Cell
			if i < len(row) {
				c = row[i]
			}
			cells[i] = renderCell(c, widths[i], style.Fg)
		}
		sb.WriteString(fmt.Sprintf("\033[%d;38;5;%d;48;5;%dm%s\033[0m\n", style.Mode, style.Fg, style.Bg, strings.Join(cells, "  ")))
	}
	return sb.String()
}

// priorityFg returns the foreground colour for a priority.
func priorityFg(priority string) int {
	switch priority {
	case PriorityCritical:
		return ColFgPriorityCritical
	case PriorityHigh:
		return ColFgPriorityHigh
	case PriorityLow:
		return ColFgPriorityLow
	default:
		return ColFgPriorityNormal
	}
}

// activeFg maps a row foreground to its "active" (inverted) variant.
func activeFg(fg int) int {
	switch fg {
	case ColFgPriorityCritical:
		return 124
	case ColFgPriorityHigh:
		return 130
	case ColFgPriorityLow:
		return 238
	default:
		return ColFgActive
	}
}

// taskRowStyle computes the style for a task row at the given index.
func taskRowStyle(task *Task, index int) RowStyle {
	fg := priorityFg(task.Priority)
	if task.IsOverdue() && task.Priority != PriorityCritical {
		fg = ColFgPriorityHigh
	}
	bg := ColBgDefault1
	if index%2 == 1 {
		bg = ColBgDefault2
	}
	switch task.Status {
	case StatusActive:
		fg = activeFg(fg)
		bg = ColBgActive
	case StatusPaused:
		bg = ColBgPaused
	}
	return RowStyle{Mode: ModeRow, Fg: fg, Bg: bg}
}

func defaultRowStyle(index int) RowStyle {
	bg := ColBgDefault1
	if index%2 == 1 {
		bg = ColBgDefault2
	}
	return RowStyle{Mode: ModeRow, Fg: ColFgDefault, Bg: bg}
}
