package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

// printJSON writes v as indented JSON without a trailing newline.
func printJSON(v interface{}) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		ExitFail("Failed to marshal JSON")
	}
	os.Stdout.Write(data)
}

func tasksForJSON(tasks Tasks) []Task {
	out := make([]Task, 0, len(tasks))
	for _, t := range tasks {
		c := *t
		if c.Tags == nil {
			c.Tags = []string{}
		}
		out = append(out, c)
	}
	return out
}

// PrintContextLine shows the active context if one applies.
func PrintContextLine(conf Config, ctx Query) {
	if ctx.String() == "" && !conf.CtxFromEnv {
		return
	}
	if conf.CtxFromEnv {
		fmt.Printf("\033[33mActive context (set by DSTASK_CONTEXT): %s\033[0m\n", ctx.String())
	} else {
		fmt.Printf("\033[33mActive context: %s\033[0m\n", ctx.String())
	}
}

// DisplayTasks shows a list of (already sorted) tasks as a table, a single
// task in detail, or JSON when not attached to a terminal.
func DisplayTasks(tasks Tasks, truncate bool) {
	if !StdoutIsTTY() {
		printJSON(tasksForJSON(tasks))
		return
	}

	if len(tasks) == 0 {
		ExitFail("No matching tasks in given context or filter.")
	}

	if len(tasks) == 1 {
		tasks[0].Display()
		return
	}

	width, height := MustGetTermSize()
	maxTasks := height - TermLinesUsed
	if maxTasks < MinTasksShown {
		maxTasks = MinTasksShown
	}

	shown := tasks
	if truncate && len(shown) > maxTasks {
		shown = shown[:maxTasks]
	}

	table := NewTable(width, "ID", "Priority", "Tags", "Due", "Project", "Summary")
	for i, task := range shown {
		table.AddRow(taskRowStyle(task, i),
			Cell{Text: fmt.Sprintf("%d", task.ID)},
			Cell{Text: task.Priority},
			Cell{Text: strings.Join(task.Tags, " ")},
			Cell{Text: FormatDue(task.Due)},
			Cell{Text: task.Project},
			Cell{Text: task.Summary, Note: task.NoteTail()},
		)
	}
	fmt.Print(table.Render())

	if len(shown) < len(tasks) {
		fmt.Printf("\n%d/%d tasks shown.\n", len(shown), len(tasks))
	} else {
		fmt.Printf("\n%d tasks.\n", len(tasks))
	}
}

// Display shows a single task in detail.
func (t *Task) Display() {
	width, _ := MustGetTermSize()
	table := NewTable(width, "Name", "Value")
	rows := [][2]string{
		{"ID", fmt.Sprintf("%d", t.ID)},
		{"Priority", t.Priority},
		{"Summary", t.Summary},
		{"Status", t.Status},
		{"Project", t.Project},
		{"Tags", strings.Join(t.Tags, ", ")},
		{"UUID", t.UUID},
		{"Created", t.Created.String()},
	}
	if !t.Resolved.IsZero() {
		rows = append(rows, [2]string{"Resolved", t.Resolved.String()})
	}
	if !t.Due.IsZero() {
		rows = append(rows, [2]string{"Due", t.Due.String()})
	}
	for i, r := range rows {
		table.AddStringRow(defaultRowStyle(i), r[0], r[1])
	}
	fmt.Print(table.Render())

	if t.Notes != "" {
		fmt.Printf("\nNotes on task %d:\n\033[38;5;%dm%s\033[0m\n\n", t.ID, ColFgGrey, t.Notes)
	}
}

// DisplayByWeek shows resolved tasks grouped by ISO week.
func DisplayByWeek(tasks Tasks) {
	if !RealStdoutIsTTY() {
		printJSON(tasksForJSON(tasks))
		return
	}

	width, _ := MustGetTermSize()
	var table *Table
	lastWeek := -1
	for _, task := range tasks {
		_, week := task.Resolved.ISOWeek()
		if week != lastWeek {
			if table != nil {
				fmt.Print(table.Render())
			}
			fmt.Printf("\n\n> Week %d, starting %s\n\n", week, task.Resolved.Format("Mon 2 Jan 2006"))
			table = NewTable(width, "Resolved", "Priority", "Tags", "Due", "Project", "Summary")
			lastWeek = week
		}
		table.AddRow(taskRowStyle(task, len(table.Rows)),
			Cell{Text: FormatResolved(task.Resolved)},
			Cell{Text: task.Priority},
			Cell{Text: strings.Join(task.Tags, " ")},
			Cell{Text: FormatDue(task.Due)},
			Cell{Text: task.Project},
			Cell{Text: task.Summary, Note: task.NoteTail()},
		)
	}
	if table != nil {
		fmt.Print(table.Render())
	}
	fmt.Printf("%d tasks.\n", len(tasks))
}

// DisplayProjects renders the project summary table.
func DisplayProjects(projects []*Project) {
	if !StdoutIsTTY() {
		printJSON(projects)
		return
	}
	width, _ := MustGetTermSize()
	table := NewTable(width, "Name", "Progress", "Created")
	i := 0
	for _, p := range projects {
		if p.TaskCount == p.ResolvedCount {
			continue
		}
		style := RowStyle{Mode: ModeRow, Fg: priorityFg(p.Priority), Bg: ColBgDefault1}
		if i%2 == 1 {
			style.Bg = ColBgDefault2
		}
		if p.Active {
			style.Fg = ColFgActive
			style.Bg = ColBgActive
		}
		table.AddStringRow(style, p.Name, fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount), p.Created.Format("Mon 2 Jan 2006"))
		i++
	}
	fmt.Print(table.Render())
}
