package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

// visibleStatuses are the statuses shown by default listings.
var visibleStatuses = []string{StatusActive, StatusPending, StatusDelegated, StatusDeferred, StatusPaused}

// filterQuery returns the effective filter: the query merged with the
// context unless IDs were given (IDs address tasks directly).
func filterQuery(query Query, ctx Query) Query {
	if len(query.IDs) > 0 {
		return query
	}
	return query.Merge(ctx)
}

func mustHaveNoOperators(query Query) {
	if query.HasOperators() {
		ExitFail("operators not valid in this context")
	}
}

func mustHaveIDs(query Query) {
	if len(query.IDs) == 0 {
		ExitFail("no ID(s) specified")
	}
}

// showTasks is the shared implementation of the listing commands.
func showTasks(conf Config, ctx Query, query Query, statuses []string, truncate bool) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(ts.AllTasks()) == 0 {
		if StdoutIsTTY() {
			fmt.Println("No tasks found. Run `dstask help` for instructions.")
			return
		}
		printJSON([]Task{})
		return
	}
	tasks := SortTasks(ts.Filter(filterQuery(query, ctx), statuses))
	if StdoutIsTTY() {
		PrintContextLine(conf, ctx)
	}
	DisplayTasks(tasks, truncate)
}

func CommandNext(conf Config, ctx Query, query Query) {
	if len(query.IDs) > 0 && query.HasOperators() {
		ExitFail("operators not valid when addressing task by ID")
	}
	showTasks(conf, ctx, query, visibleStatuses, true)
}

func CommandShowOpen(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, visibleStatuses, false)
}

func CommandShowActive(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, []string{StatusActive}, true)
}

func CommandShowPaused(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, []string{StatusPaused}, true)
}

func CommandShowTemplates(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, []string{StatusTemplate}, true)
}

func CommandShowUnorganised(conf Config, ctx Query, query Query) {
	if len(query.IDs) > 0 || query.HasOperators() {
		ExitFail("query/context not used for show-unorganised")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(ts.AllTasks()) == 0 {
		if StdoutIsTTY() {
			fmt.Println("No tasks found. Run `dstask help` for instructions.")
			return
		}
		printJSON([]Task{})
		return
	}
	var tasks Tasks
	for _, task := range ts.Filter(Query{}, visibleStatuses) {
		if len(task.Tags) == 0 && task.Project == "" {
			tasks = append(tasks, task)
		}
	}
	tasks = SortTasks(tasks)
	if StdoutIsTTY() {
		PrintContextLine(conf, ctx)
	}
	DisplayTasks(tasks, true)
}

func CommandShowResolved(conf Config, ctx Query, query Query) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, true)
	tasks := ts.Filter(filterQuery(query, ctx), []string{StatusResolved})
	sorted := make(Tasks, len(tasks))
	copy(sorted, tasks)
	sort.Stable(ByResolved(sorted))
	if len(sorted) > MaxResolved {
		sorted = sorted[len(sorted)-MaxResolved:]
	}
	DisplayByWeek(sorted)
}

func CommandShowProjects(conf Config, ctx Query, query Query) {
	if len(query.IDs) > 0 || query.HasOperators() {
		ExitFail("query/context not supported for show-projects")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, true)
	projects := ts.GetProjects()
	if projects == nil {
		projects = []*Project{}
	}
	DisplayProjects(projects)
}

func CommandShowTags(conf Config, ctx Query, query Query) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	tasks := ts.Filter(filterQuery(query, ctx), visibleStatuses)
	for tag := range GetTags(tasks) {
		fmt.Println(tag)
	}
}

// newTaskFromQuery builds a task from the query, using a template if given.
func newTaskFromQuery(ts *TaskSet, query Query) Task {
	if query.Template > 0 {
		tmpl := ts.MustGetByID(query.Template)
		task := *tmpl
		task.UUID = ""
		task.ID = 0
		task.Status = StatusPending
		task.Created = time.Time{}
		task.Resolved = time.Time{}
		task.Tags = append([]string{}, tmpl.Tags...)
		task.Subtasks = append([]SubTask{}, tmpl.Subtasks...)
		task.Dependencies = append([]string{}, tmpl.Dependencies...)
		task.Modify(query)
		if query.Text != "" {
			task.Summary = query.Text
		}
		task.writePending = false
		return task
	}
	return TaskFromQuery(query)
}

func CommandAdd(conf Config, ctx Query, query Query) {
	if query.Text == "" && query.Template == 0 {
		ExitFail("task description or template required")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	query = query.Merge(ctx)
	task := newTaskFromQuery(ts, query)
	t := ts.AddTask(task)
	PrintContextLine(conf, ctx)
	ts.SavePendingChanges()
	MustGitCommit(conf.Repo, "Added %d: %s", t.ID, t.Summary)
}

func CommandLog(conf Config, ctx Query, query Query) {
	if query.Text == "" {
		ExitFail("task description required")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	query = query.Merge(ctx)
	task := newTaskFromQuery(ts, query)
	task.Status = StatusResolved
	task.Resolved = time.Now()
	t := ts.AddTask(task)
	PrintContextLine(conf, ctx)
	ts.SavePendingChanges()
	MustGitCommit(conf.Repo, "Logged %s", t.Summary)
}

func CommandTemplate(conf Config, ctx Query, query Query) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) > 0 {
		for _, id := range query.IDs {
			task := ts.MustGetByID(id)
			task.Status = StatusTemplate
			ts.MustUpdateTask(task)
			ts.SavePendingChanges()
			MustGitCommit(conf.Repo, "Changed %d: %s to Template", task.ID, task.Summary)
		}
		return
	}
	if query.Text != "" {
		query = query.Merge(ctx)
		task := newTaskFromQuery(ts, query)
		task.Status = StatusTemplate
		t := ts.AddTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "Created Template %d: %s", t.ID, t.Summary)
	}
}

func CommandStart(conf Config, ctx Query, query Query) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) > 0 {
		for _, id := range query.IDs {
			task := ts.MustGetByID(id)
			if err := task.SetStatus(StatusActive); err != nil {
				ExitFail("%s", err.Error())
			}
			ts.MustUpdateTask(task)
			ts.SavePendingChanges()
			MustGitCommit(conf.Repo, "Started %d: %s", task.ID, task.Summary)
			if task.Notes != "" {
				fmt.Printf("\nNotes on task %d:\n\033[38;5;%dm%s\033[0m\n\n", task.ID, ColFgGrey, task.Notes)
			}
		}
		return
	}
	if query.Text != "" {
		query = query.Merge(ctx)
		task := newTaskFromQuery(ts, query)
		task.Status = StatusActive
		t := ts.AddTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "Added and started %d: %s", t.ID, t.Summary)
		return
	}
	ExitFail("nothing to do -- specify an ID or describe a task")
}

func commandSetStatus(conf Config, query Query, status string, verb string) {
	mustHaveIDs(query)
	mustHaveNoOperators(query)
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if err := task.SetStatus(status); err != nil {
			ExitFail("%s", err.Error())
		}
		if query.Text != "" {
			task.Notes = task.Notes + "\n" + query.Text
		}
		ts.MustUpdateTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "%s %d: %s", verb, id, task.Summary)
	}
}

func CommandStop(conf Config, ctx Query, query Query) {
	commandSetStatus(conf, query, StatusPaused, "Stopped")
}

func CommandDone(conf Config, ctx Query, query Query) {
	commandSetStatus(conf, query, StatusResolved, "Resolved")
}

func CommandNote(conf Config, ctx Query, query Query) {
	mustHaveIDs(query)
	mustHaveNoOperators(query)
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if query.Text == "" {
			data := MustEditBytes([]byte(task.Notes), fmt.Sprintf("dstask.*.%d-%s.md", task.ID, taskSlug(task)))
			task.Notes = string(data)
		} else if task.Notes == "" {
			task.Notes = query.Text
		} else {
			task.Notes = task.Notes + "\n" + query.Text
		}
		ts.MustUpdateTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "Edit note %d: %s", task.ID, task.Summary)
	}
}

// taskSlug produces a filesystem friendly fragment of the summary.
func taskSlug(task *Task) string {
	var sb strings.Builder
	for _, r := range strings.ToLower(task.Summary) {
		switch {
		case (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9'):
			sb.WriteRune(r)
		case r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f':
			s := sb.String()
			if s != "" && !strings.HasSuffix(s, "-") {
				sb.WriteByte('-')
			}
		}
	}
	slug := sb.String()
	if len(slug) > 21 {
		slug = slug[:21]
	}
	return slug
}

func CommandModify(conf Config, ctx Query, query Query) {
	if !query.HasOperators() {
		ExitFail("no operations specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)

	if len(query.IDs) == 0 {
		tasks := ts.Filter(ctx, visibleStatuses)
		ConfirmOrAbort("no IDs specified. Apply to all %d tasks in current ctx?", len(tasks))
		for _, task := range tasks {
			task.Modify(query)
			ts.MustUpdateTask(task)
			ts.SavePendingChanges()
			MustGitCommit(conf.Repo, "Modified %d: %s", task.ID, task.Summary)
		}
		return
	}

	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		task.Modify(query)
		ts.MustUpdateTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "Modified %d: %s", task.ID, task.Summary)
	}
}

func CommandEdit(conf Config, ctx Query, query Query) {
	mustHaveIDs(query)
	mustHaveNoOperators(query)
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
