)

// visibleStatuses are the statuses shown by default listings.
var visibleStatuses = []string{StatusActive, StatusPending, StatusDelegated, StatusDeferred, StatusPaused}

// filterQuery returns the effective filter: the query merged with the
// context unless IDs were given (IDs address tasks directly).
func filterQuery(query Query, ctx Query) Query {
	if len(query.IDs) > 0 {
		return query
	}
	return query.Merge(ctx)
}

func mustHaveNoOperators(query Query) {
	if query.HasOperators() {
		ExitFail("operators not valid in this context")
	}
}

func mustHaveIDs(query Query) {
	if len(query.IDs) == 0 {
		ExitFail("no ID(s) specified")
	}
}

// showTasks is the shared implementation of the listing commands.
func showTasks(conf Config, ctx Query, query Query, statuses []string, truncate bool) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(ts.AllTasks()) == 0 {
		if StdoutIsTTY() {
			fmt.Println("No tasks found. Run `dstask help` for instructions.")
			return
		}
		printJSON([]Task{})
		return
	}
	tasks := SortTasks(ts.Filter(filterQuery(query, ctx), statuses))
	if StdoutIsTTY() {
		PrintContextLine(conf, ctx)
	}
	DisplayTasks(tasks, truncate)
}

func CommandNext(conf Config, ctx Query, query Query) {
	if len(query.IDs) > 0 && query.HasOperators() {
		ExitFail("operators not valid when addressing task by ID")
	}
	showTasks(conf, ctx, query, visibleStatuses, true)
}

func CommandShowOpen(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, visibleStatuses, false)
}

func CommandShowActive(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, []string{StatusActive}, true)
}

func CommandShowPaused(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, []string{StatusPaused}, true)
}

func CommandShowTemplates(conf Config, ctx Query, query Query) {
	showTasks(conf, ctx, query, []string{StatusTemplate}, true)
}

func CommandShowUnorganised(conf Config, ctx Query, query Query) {
	if len(query.IDs) > 0 || query.HasOperators() {
		ExitFail("query/context not used for show-unorganised")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(ts.AllTasks()) == 0 {
		if StdoutIsTTY() {
			fmt.Println("No tasks found. Run `dstask help` for instructions.")
			return
		}
		printJSON([]Task{})
		return
	}
	var tasks Tasks
	for _, task := range ts.Filter(Query{}, visibleStatuses) {
		if len(task.Tags) == 0 && task.Project == "" {
			tasks = append(tasks, task)
		}
	}
	tasks = SortTasks(tasks)
	if StdoutIsTTY() {
		PrintContextLine(conf, ctx)
	}
	DisplayTasks(tasks, true)
}

func CommandShowResolved(conf Config, ctx Query, query Query) {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, true)
	tasks := ts.Filter(filterQuery(query, ctx), []string{StatusResolved})
	sorted := make(Tasks, len(tasks))
	copy(sorted, tasks)
	sort.Stable(ByResolved(sorted))
	if len(sorted) > MaxResolved {
		sorted = sorted[len(sorted)-MaxResolved:]
	}
	DisplayByWeek(sorted)
}

func CommandShowProjects(conf Config, ctx Query, query Query) {
	if len(query.IDs) > 0 || query.HasOperators() {
		ExitFail("query/context not supported for show-projects")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, true)
	projects := ts.GetProjects()
	if projects == nil {
