	if query.Text == "" && query.Template == 0 {
		ExitFail("task description or template required")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	query = query.Merge(ctx)
	task := newTaskFromQuery(ts, query)
	t := ts.AddTask(task)
	PrintContextLine(conf, ctx)
	ts.SavePendingChanges()
	MustGitCommit(conf.Repo, "Added %d: %s", t.ID, t.Summary)
