			MustGitCommit(conf.Repo, "Started %d: %s", task.ID, task.Summary)
			if task.Notes != "" {
				fmt.Printf("\nNotes on task %d:\n\033[38;5;%dm%s\033[0m\n\n", task.ID, ColFgGrey, task.Notes)
			}
		}
		return
	}
	if query.Text != "" {
		query = query.Merge(ctx)
		task := newTaskFromQuery(ts, query)
		task.Status = StatusActive
		t := ts.AddTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "Added and started %d: %s", t.ID, t.Summary)
		return
	}
	ExitFail("nothing to do -- specify an ID or describe a task")
}

func commandSetStatus(conf Config, query Query, status string, verb string) {
	mustHaveIDs(query)
	mustHaveNoOperators(query)
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if err := task.SetStatus(status); err != nil {
			ExitFail("%s", err.Error())
		}
		if query.Text != "" {
			task.Notes = task.Notes + "\n" + query.Text
		}
		ts.MustUpdateTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "%s %d: %s", verb, id, task.Summary)
	}
}

func CommandStop(conf Config, ctx Query, query Query) {
