func CommandNote(conf Config, ctx Query, query Query) {
	mustHaveIDs(query)
	mustHaveNoOperators(query)
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if query.Text == "" {
			data := MustEditBytes([]byte(task.Notes), fmt.Sprintf("dstask.*.%d-%s.md", task.ID, taskSlug(task)))
			task.Notes = string(data)
		} else if task.Notes == "" {
			task.Notes = query.Text
		} else {
			task.Notes = task.Notes + "\n" + query.Text
		}
		ts.MustUpdateTask(task)
		ts.SavePendingChanges()
		MustGitCommit(conf.Repo, "Edit note %d: %s", task.ID, task.Summary)
	}
}

// taskSlug produces a filesystem friendly fragment of the summary.
func taskSlug(task *Task) string {
	var sb strings.Builder
	for _, r := range strings.ToLower(task.Summary) {
		switch {
		case (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9'):
			sb.WriteRune(r)
		case r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f':
			s := sb.String()
			if s != "" && !strings.HasSuffix(s, "-") {
				sb.WriteByte('-')
			}
		}
	}
	slug := sb.String()
	if len(slug) > 21 {
		slug = slug[:21]
	}
	return slug
}

