new = '''// decodeDoubleQuotedBody decodes escape sequences in the body of a double
// quoted scalar (without the surrounding quotes).
func decodeDoubleQuotedBody(body string, line int) string {
	var sb strings.Builder
	for i := 0; i < len(body); {
		c := body[i]
		if c == '\\\\' {
			if i+1 >= len(body) {
				panic(&yamlSyntaxError{line, "found unexpected end of stream"})
			}
			n, w := decodeEscape(body[i+1:], line)
			sb.WriteString(n)
			i += 1 + w
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String()
}

// findClosingDouble finds the index of the closing double quote in s (which
// does not include the opening quote), or -1.
func findClosingDouble(s string) int {
	for i := 0; i < len(s); i++ {
		if s[i] == '\\\\' {
			i++
			continue
		}
		if s[i] == '"' {
			return i
		}
	}
	return -1
}

// findClosingSingle finds the closing single quote (not doubled), or -1.
func findClosingSingle(s string) int {
	for i := 0; i < len(s); i++ {
		if s[i] == '\\'' {
			if i+1 < len(s) && s[i+1] == '\\'' {
				i++
				continue
			}
			return i
		}
	}
	return -1
}

func (p *yParser) parseQuotedScalar(parentIndent int, text string, lineNum int) *yNode {
	q := text[0]
	var sb strings.Builder
	seg := text[1:]
	curLine := lineNum
	escapedBreak := false
	for {
		var close int
		if q == '"' {
			close = findClosingDouble(seg)
		} else {
			close = findClosingSingle(seg)
		}
		if close >= 0 {
			body := seg[:close]
			if q == '"' {
				sb.WriteString(decodeDoubleQuotedBody(body, curLine))
			} else {
