words = ['fix','bug','write','report','call','mum','buy','milk','deploy','server','review','pr','plan','trip']
tags = ['+work','+home','+urgent','+later','+x']
projects = ['project:web','project:house','project:ops','project:misc']
prios = ['P0','P1','P2','P3']
cmds = []
for i in range(40):
    summary = ' '.join(random.sample(words, random.randint(1,4)))
    args = ['add'] + summary.split()
    if random.random() < 0.7: args.append(random.choice(tags))
    if random.random() < 0.3: args.append(random.choice(tags))
    if random.random() < 0.5: args.append(random.choice(projects))
    if random.random() < 0.4: args.append(random.choice(prios))
    if random.random() < 0.3: args += ['due:' + random.choice(['today','tomorrow','yesterday','2026-12-01','next-friday','15'])]
    if random.random() < 0.3: args += ['/', 'some', 'note', 'text']
    cmds.append(args)
    r = random.random()
    if r < 0.15: cmds.append([str(random.randint(1, i+1)), 'start'])
    elif r < 0.25: cmds.append([str(random.randint(1, i+1)), 'stop'])
    elif r < 0.35: cmds.append([str(random.randint(1, i+1)), 'done'])
    elif r < 0.45: cmds.append([str(random.randint(1, i+1)), 'modify', random.choice(tags), random.choice(prios)])
    elif r < 0.5: cmds.append([str(random.randint(1, i+1)), 'note', 'extra', 'note'])
for c in (['next'], ['show-open'], ['show-active'], ['show-paused'], ['show-projects'], ['show-tags'], ['show-unorganised'], ['next', '+work'], ['next', 'project:web'], ['next', 'P1'], ['next', '--', 'P0'], ['1'], ['2'], ['3']):
    cmds.append({'cmd': c, 'pty': (100, 30)})
    cmds.append({'cmd': c, 'pty': (60, 15)})
cmds.append({'cmd': ['show-resolved'], 'pty': (100, 30)})
cmds.append(['show-resolved'])
cmds.append(['next'])
scenario(cmds, 'random-mix')
